        allowedPrefixes: [projectRoot],
        allowHidden: true,
      });

      const result = await hiddenValidator.validate('/workspaces/project/config/.env');
      expect(result.isValid).toBe(false);
      expect(result.errors.some(e => e.includes('.env'))).toBe(true);
