      // When
      const result = pathValidator.sanitize(unsafePath);

      // Then
      expect(result).not.toContain('\0');
    });

    it('should truncate paths exceeding max length', () => {
      // Given
      const longPath = 'a'.repeat(pathConfig.maxPathLength + 100);

      // When
      const result = pathValidator.sanitize(longPath);

      // Then
      expect(result.length).toBeLessThanOrEqual(pathConfig.maxPathLength);
    });

    it('should normalize the sanitized path', () => {
      // Given
      const path = 'valid/path/file.ts';

      // When
      pathValidator.sanitize(path);

      // Then
      expect(mockPathUtils.normalize).toHaveBeenCalled();
    });
  });

  describe('CVE prevention scenarios', () => {
    it('should block CVE-1: directory traversal attack', () => {
      // Given - Various traversal attempts
      const attacks = [
        '../../../etc/passwd',
        '..\\..\\..\\Windows\\System32\\config\\SAM',
        'valid/path/../../../etc/passwd',
        '....//....//....//etc/passwd',
      ];

      // When/Then
      for (const attack of attacks) {
        expect(pathValidator.isValid(attack)).toBe(false);
      }
    });

    it('should block CVE-2: absolute path injection', () => {
      // Given - Absolute path attempts
      const attacks = [
        '/etc/passwd',
        '/var/log/auth.log',
        '/tmp/malicious',
      ];

      // When/Then
      for (const attack of attacks) {
        expect(pathValidator.isValid(attack)).toBe(false);
      }
    });

    it('should block CVE-3: null byte injection', () => {
      // Given - Null byte attempts
      const attacks = [
        'file.txt\0',
        'image.png\0.exe',
        '\0/etc/passwd',
      ];

      // When/Then
      for (const attack of attacks) {
        expect(pathValidator.isValid(attack)).toBe(false);
      }
    });

    it('should block encoded traversal attempts', () => {
      // Given - URL encoded traversal
      const path = '%2e%2e%2f%2e%2e%2f%2e%2e%2fetc/passwd';

      // When - After decoding, should still be blocked
      const decoded = decodeURIComponent(path);
      const result = pathValidator.isValid(decoded);

      // Then
      expect(result).toBe(false);
    });
  });

  describe('edge cases', () => {
    it('should handle Windows-style paths', () => {
      // Given
      const windowsPath = 'C:\\Users\\test\\file.txt';

      // When
      const result = pathValidator.isValid(windowsPath);

      // Then - Windows paths should be evaluated based on patterns
      expect(typeof result).toBe('boolean');
    });

    it('should handle unicode in paths', () => {
      // Given
      const unicodePath = 'src/modules/\u0000.ts';

      // When
      const result = pathValidator.isValid(unicodePath);

      // Then
      expect(result).toBe(false); // Contains null character
    });

    it('should handle paths with only dots', () => {
      // Given
      const dotsPath = '...';

      // When
      const result = pathValidator.isValid(dotsPath);

      // Then
      expect(result).toBe(true); // Not a traversal pattern
    });

    it('should handle paths with special characters', () => {
      // Given
      const specialPath = 'src/file-name_v2.0.1.ts';

      // When
      const result = pathValidator.isValid(specialPath);

      // Then
      expect(result).toBe(true);
    });
  });
});

/**
 * V3 Claude-Flow Safe Executor Unit Tests
 *
 * London School TDD - Behavior Verification
 * Tests secure command execution (CVE-3 prevention)
 */
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { createMock, type MockedInterface } from '../helpers/create-mock';
import { securityConfigs } from '../fixtures/configurations';

/**
 * Safe executor interface (to be implemented)
 */
interface ISafeExecutor {
  execute(command: string, args?: string[], options?: ExecuteOptions): Promise<ExecuteResult>;
  isCommandAllowed(command: string): boolean;
  sanitizeArgs(args: string[]): string[];
}

/**
 * Process spawner interface (collaborator)
 */
interface IProcessSpawner {
  spawn(command: string, args: string[], options: SpawnOptions): Promise<SpawnResult>;
  kill(pid: number): Promise<void>;
}

/**
 * Command validator interface (collaborator)
 */
interface ICommandValidator {
  extractCommand(input: string): string;
  isBuiltin(command: string): boolean;
  resolveCommand(command: string): Promise<string | null>;
}

interface ExecuteOptions {
  timeout?: number;
  cwd?: string;
  env?: Record<string, string>;
  shell?: boolean;
}

interface ExecuteResult {
  stdout: string;
  stderr: string;
  exitCode: number;
  killed: boolean;
}

interface SpawnOptions {
  cwd?: string;
  env?: Record<string, string>;
  timeout?: number;
  shell?: boolean;
}

interface SpawnResult {
  pid: number;
  stdout: string;
  stderr: string;
  exitCode: number;
  signal?: string;
}

/**
 * Safe executor implementation for testing
 */
class SafeExecutor implements ISafeExecutor {
  constructor(
    private readonly spawner: IProcessSpawner,
    private readonly validator: ICommandValidator,
    private readonly config: typeof securityConfigs.strict.execution
  ) {}

  async execute(
    command: string,
    args: string[] = [],
    options: ExecuteOptions = {}
  ): Promise<ExecuteResult> {
    // Extract base command
    const baseCommand = this.validator.extractCommand(command);

    // Check if command is allowed
    if (!this.isCommandAllowed(baseCommand)) {
      throw new Error(`Command not allowed: ${baseCommand}`);
    }

    // Sanitize arguments
    const sanitizedArgs = this.sanitizeArgs(args);

    // Apply shell restriction from config
    const spawnOptions: SpawnOptions = {
      cwd: options.cwd,
      env: options.env,
      timeout: options.timeout ?? this.config.timeout,
      shell: this.config.shell, // Always use config, ignore user option
    };

    const result = await this.spawner.spawn(baseCommand, sanitizedArgs, spawnOptions);

    return {
      stdout: result.stdout,
      stderr: result.stderr,
      exitCode: result.exitCode,
      killed: result.signal !== undefined,
    };
  }

  isCommandAllowed(command: string): boolean {
    const baseCommand = this.validator.extractCommand(command);

    // Check blocked commands first
    if (this.config.blockedCommands.includes(baseCommand)) {
      return false;
    }

    // Check allowed commands
    return this.config.allowedCommands.includes(baseCommand);
  }

  sanitizeArgs(args: string[]): string[] {
    return args.map(arg => {
      // Remove shell metacharacters
      let sanitized = arg
        .replace(/[;&|`$()]/g, '')
        .replace(/\n/g, '')
        .replace(/\r/g, '');

      // Remove command substitution
      sanitized = sanitized.replace(/\$\([^)]*\)/g, '');
      sanitized = sanitized.replace(/`[^`]*`/g, '');

      // Remove redirection
      sanitized = sanitized.replace(/[<>]/g, '');

      return sanitized;
    });
  }
}

