/**
 * Security Application Service - Application Layer
 *
 * Orchestrates security operations and provides simplified interface.
 *
 * @module v3/security/application/services
 */

import { SecurityContext, PermissionLevel } from '../../domain/entities/security-context.js';
import { SecurityDomainService, ValidationResult, ThreatDetectionResult } from '../../domain/services/security-domain-service.js';

/**
 * Security audit result
 */
export interface SecurityAuditResult {
  passed: boolean;
  score: number;
  checks: Array<{
    name: string;
    passed: boolean;
    severity: 'low' | 'medium' | 'high' | 'critical';
    message: string;
  }>;
  recommendations: string[];
}

/**
 * Security Application Service
 */
export class SecurityApplicationService {
  private readonly domainService: SecurityDomainService;
  private readonly contexts: Map<string, SecurityContext> = new Map();

  constructor() {
    this.domainService = new SecurityDomainService();
  }

  // ============================================================================
  // Context Management
  // ============================================================================

  /**
   * Create and register security context for agent
   */
  createAgentContext(agentId: string, role: string): SecurityContext {
    const context = this.domainService.createAgentContext(agentId, role);
    this.contexts.set(agentId, context);
    return context;
  }

  /**
   * Get security context
   */
  getContext(principalId: string): SecurityContext | undefined {
    return this.contexts.get(principalId);
  }

  /**
   * Remove security context
   */
  removeContext(principalId: string): boolean {
    return this.contexts.delete(principalId);
  }

  // ============================================================================
  // Validation
  // ============================================================================

  /**
   * Validate path access
   */
  validatePath(path: string, principalId: string): ValidationResult {
    const context = this.contexts.get(principalId);
    if (!context) {
      return {
        valid: false,
        errors: ['Security context not found'],
        warnings: [],
      };
    }

    return this.domainService.validatePath(path, context);
  }

  /**
   * Validate command execution
   */
  validateCommand(command: string, principalId: string): ValidationResult {
    const context = this.contexts.get(principalId);
    if (!context) {
      return {
        valid: false,
        errors: ['Security context not found'],
        warnings: [],
      };
    }

    return this.domainService.validateCommand(command, context);
  }

  /**
   * Validate user input
   */
  validateInput(input: string): ValidationResult {
    return this.domainService.validateInput(input);
  }

  /**
   * Detect threats in content
   */
  detectThreats(content: string): ThreatDetectionResult {
    return this.domainService.detectThreats(content);
  }

  // ============================================================================
  // Audit
  // ============================================================================

  /**
   * Run security audit on codebase
   */
  async auditCodebase(files: Array<{ path: string; content: string }>): Promise<SecurityAuditResult> {
    const checks: SecurityAuditResult['checks'] = [];
    const recommendations: string[] = [];
    let criticalCount = 0;
    let highCount = 0;

    for (const file of files) {
      const threats = this.domainService.detectThreats(file.content);

      for (const threat of threats.threats) {
        checks.push({
          name: `${threat.type} in ${file.path}`,
          passed: false,
          severity: threat.severity,
          message: threat.description,
        });

        if (threat.severity === 'critical') criticalCount++;
        if (threat.severity === 'high') highCount++;
      }

      if (threats.safe) {
        checks.push({
          name: `Security check: ${file.path}`,
          passed: true,
          severity: 'low',
          message: 'No threats detected',
        });
      }
    }

    // Generate recommendations
    if (criticalCount > 0) {
      recommendations.push('Address critical security issues immediately');
    }
    if (highCount > 0) {
      recommendations.push('Review and fix high-severity findings');
    }
    recommendations.push('Run regular security scans');
    recommendations.push('Keep dependencies updated');

    // Calculate score
    const totalChecks = checks.length;
    const passedChecks = checks.filter((c) => c.passed).length;
    const score = totalChecks > 0 ? Math.round((passedChecks / totalChecks) * 100) : 100;

    return {
      passed: criticalCount === 0 && highCount === 0,
      score,
      checks,
      recommendations,
    };
  }

  /**
   * Check if operation is allowed
   */
  isOperationAllowed(
    principalId: string,
    operation: 'path' | 'command',
    target: string
  ): boolean {
    const context = this.contexts.get(principalId);
    if (!context || context.isExpired()) return false;

    if (operation === 'path') {
      return context.canAccessPath(target);
    } else {
      return context.canExecuteCommand(target);
    }
  }
}

/**
 * AgentAuthorizationPropagator — action-layer security for agent delegation.
 *
 * Implements P1 of ADR-144 (ruvnet/ruflo#2248): scope-envelope on SendMessage
 * + per-action authorization checks. P2-P5 wire this into the comms layer,
 * MCP dispatcher, MCP auth validator, and provenance log respectively.
 *
 * Threat model
 * ------------
 * When agent A delegates a task to agent B via SendMessage, B can today
 * escalate the granted scope by calling tools A was never authorized to
 * invoke. RBAC/ABAC on agent roles do not solve this — roles don't compose
 * under dynamic LLM delegation (arXiv:2605.05440, Grade A formal analysis).
 *
 * The fix is scope-based propagation: every SendMessage carries an
 * `AuthScope` that is *monotonically reducing* — each hop can drop tools or
 * servers from the granted set but never add them. This is the same shape
 * as OAuth scope reduction; adding back a tool requires talking to the
 * original principal out-of-band.
 *
 * Scope
 * -----
 * - P1 (this file): the component, the envelope, the type-level invariants.
 *   No call sites yet — adding the wrapping/enforcement in P2-P4.
 * - All operations synchronous, pure, allocation-light. Targets < 1 ms p99
 *   for `wrapOutbound` + `checkToolCall` so it can sit on every SendMessage.
 *
 * Backwards compatibility
 * -----------------------
 * `scope` on the envelope is optional in v1. Agents without scope set
 * operate in legacy permissive mode (all tools allowed, depth unlimited,
 * server auth unchecked). `CLAUDE_FLOW_STRICT_AUTH=true` enables enforcement.
 *
 * Reference: ADR-144, arXiv:2605.05440 (Authorization Propagation),
 * arXiv:2605.28914 (AIRGuard), arXiv:2605.22333 (MCP auth survey).
 */

/** Scope granted to an agent at a delegation hop. Monotonically reducing. */
export interface AuthScope {
  /** Stable identifier of the originating principal (agent or user). */
  readonly principalId: string;
  /** MCP tool IDs this scope is allowed to call. */
  readonly grantedTools: ReadonlyArray<string>;
  /** MCP server IDs whose tool responses this scope will accept. */
  readonly grantedServers: ReadonlyArray<string>;
  /** Max remaining delegation hops. Decrements on every `wrapOutbound`. */
  readonly delegationDepth: number;
  /** Unix ms after which this scope is no longer valid. */
  readonly expiresAt: number;
  /**
   * Optional opaque ID for cross-referencing with ADR-144 P5 provenance log
   * and ADR-146 telemetry events. Callers should treat as a correlation
   * handle, not a security claim.
   */
  readonly scopeId?: string;
}

/** Envelope shape attached to every SendMessage when strict-auth is on. */
export interface SendMessageEnvelope<T = unknown> {
  /** Authorization scope governing what the receiver may do. */
  readonly scope: AuthScope;
  /** The original SendMessage payload, untouched. */
  readonly payload: T;
}

/** Decision returned by `checkToolCall`. Never throws. */
export interface ToolCallDecision {
  readonly allowed: boolean;
  /** Human-readable reason; stable enough to match in tests/telemetry. */
  readonly reason?:
    | 'tool-not-in-scope'
    | 'server-not-in-scope'
    | 'scope-expired'
    | 'delegation-depth-exhausted'
    | 'principal-mismatch';
}

/**
 * Wrap-failure reasons surfaced to callers as a typed error. We use a
 * discriminated union rather than throwing so the comms layer (P2) can
 * decide whether to drop the SendMessage or surface to the user.
 */
export class AuthorizationPropagationError extends Error {
  constructor(
    public readonly code:
      | 'scope-cannot-grow'
      | 'depth-underflow'
      | 'scope-expired'
      | 'principal-mismatch',
    message: string,
  ) {
    super(message);
    this.name = 'AuthorizationPropagationError';
  }
}

/**
 * Construct a default permissive scope. Used in legacy mode when no scope
 * was attached upstream. Callers SHOULD migrate to explicit scopes; this is
 * here so the propagator never has to special-case "no scope".
 */
export function makeLegacyPermissiveScope(principalId = 'legacy'): AuthScope {
  return {
    principalId,
    grantedTools: ['*'],     // sentinel — see `checkToolCall`
    grantedServers: ['*'],
    delegationDepth: Number.MAX_SAFE_INTEGER,
    expiresAt: Number.MAX_SAFE_INTEGER,
  };
}

/**
 * `AgentAuthorizationPropagator` — the load-bearing component for ADR-144.
 *
 * Construction is intentionally cheap (no I/O, no async). Callers can build
 * a fresh instance per task without overhead, or share one — it holds no
 * mutable state beyond the optional provenance buffer.
 */
export class AgentAuthorizationPropagator {
  /**
   * In-memory provenance buffer. P5 will flush this to the structured
   * telemetry sink (ADR-146 GuardrailEvent shape). For P1 we just retain
   * the last N events for inspection/tests.
   */
  private readonly provenance: Array<{
    agentId: string;
    toolId: string;
    scope: AuthScope;
    outcome: 'allowed' | 'denied';
    reason?: string;
    ts: number;
  }> = [];

  constructor(private readonly opts: { provenanceBufferMax?: number } = {}) {}

  /**
   * Attach a reduced scope to an outbound SendMessage.
   *
   * Invariants enforced (throws `AuthorizationPropagationError` on violation):
   *   - newly granted tools MUST be a subset of `currentScope.grantedTools`
   *   - newly granted servers MUST be a subset of `currentScope.grantedServers`
   *   - delegationDepth MUST decrement by ≥ 1 (must remain ≥ 0)
   *   - principalId is propagated unchanged
   *   - expiresAt cannot be extended; copied from the holder
   */
  wrapOutbound<T>(
    payload: T,
    currentScope: AuthScope,
    requested: { tools?: ReadonlyArray<string>; servers?: ReadonlyArray<string> } = {},
  ): SendMessageEnvelope<T> {
    if (currentScope.delegationDepth <= 0) {
      throw new AuthorizationPropagationError(
        'depth-underflow',
        `cannot delegate further — delegationDepth=${currentScope.delegationDepth}`,
      );
    }
    const now = Date.now();
    if (currentScope.expiresAt <= now) {
      throw new AuthorizationPropagationError(
        'scope-expired',
        `scope expired at ${new Date(currentScope.expiresAt).toISOString()}`,
      );
    }

    const reducedTools = subsetOrThrow(
      currentScope.grantedTools,
      requested.tools ?? currentScope.grantedTools,
      'tools',
    );
    const reducedServers = subsetOrThrow(
      currentScope.grantedServers,
      requested.servers ?? currentScope.grantedServers,
      'servers',
    );

    const reducedScope: AuthScope = {
      principalId: currentScope.principalId,
      grantedTools: reducedTools,
      grantedServers: reducedServers,
      delegationDepth: currentScope.delegationDepth - 1,
      expiresAt: currentScope.expiresAt,
      scopeId: currentScope.scopeId,
    };

    return { scope: reducedScope, payload };
  }

  /**
   * Validate a single tool call against a scope. Pure; never throws. Use the
   * result's `allowed` to make the dispatch decision.
   */
  checkToolCall(
    toolId: string,
    scope: AuthScope,
    opts: { serverId?: string; now?: number } = {},
  ): ToolCallDecision {
    const now = opts.now ?? Date.now();
    if (scope.expiresAt <= now) return { allowed: false, reason: 'scope-expired' };

    if (!matchesScopeList(scope.grantedTools, toolId)) {
      return { allowed: false, reason: 'tool-not-in-scope' };
    }
    if (opts.serverId && !matchesScopeList(scope.grantedServers, opts.serverId)) {
      return { allowed: false, reason: 'server-not-in-scope' };
    }
    return { allowed: true };
  }

  /**
   * Verify an MCP server presented a valid credential before its response is
   * consumed. P1 ships a permissive default (any non-empty credential is
   * accepted) so the API is stable; P4 wires this to a real validator.
   *
   * Returns `false` on missing/empty credential; callers MUST treat `false`
   * as a hard reject (same rule as ADR-131 reject findings).
   */
  verifyServerAuth(serverId: string, credential: unknown): boolean {
    if (!serverId || typeof serverId !== 'string') return false;
    if (credential == null) return false;
    if (typeof credential === 'string' && credential.trim().length === 0) return false;
    return true;
  }

  /**
   * Record an action in the provenance buffer. P5 will route to telemetry;
   * P1 keeps the last N events for test inspection and post-incident audit.
   */
  recordAction(
    agentId: string,
    toolId: string,
    scope: AuthScope,
    outcome: 'allowed' | 'denied',
    reason?: string,
  ): void {
    const max = this.opts.provenanceBufferMax ?? 1024;
    this.provenance.push({ agentId, toolId, scope, outcome, reason, ts: Date.now() });
    if (this.provenance.length > max) this.provenance.splice(0, this.provenance.length - max);
  }

  /** Read-only view of recorded provenance for tests + audit CLI (P5). */
  getProvenance(): ReadonlyArray<{
    agentId: string;
    toolId: string;
    scope: AuthScope;
    outcome: 'allowed' | 'denied';
    reason?: string;
    ts: number;
  }> {
    return this.provenance.slice();
  }
}

// ─── helpers ────────────────────────────────────────────────────────────

function subsetOrThrow(
  parent: ReadonlyArray<string>,
  requested: ReadonlyArray<string>,
  kind: 'tools' | 'servers',
): ReadonlyArray<string> {
  if (parent.includes('*')) return Array.from(new Set(requested));
  for (const item of requested) {
    if (!parent.includes(item) && item !== '*') {
      throw new AuthorizationPropagationError(
        'scope-cannot-grow',
        `cannot grant ${kind} '${item}' — not in parent scope`,
      );
    }
  }
  // De-duplicate; preserve requested order
  const seen = new Set<string>();
  const out: string[] = [];
  for (const r of requested) if (!seen.has(r)) (seen.add(r), out.push(r));
  return out;
}

function matchesScopeList(list: ReadonlyArray<string>, item: string): boolean {
  if (list.includes('*')) return true;
  return list.includes(item);
}

/**
 * Credential Generator - CVE-3 Remediation
 *
 * Fixes hardcoded default credentials by providing secure random
 * credential generation for installation and runtime.
 *
 * Security Properties:
 * - Uses crypto.randomBytes for cryptographically secure randomness
 * - Configurable entropy levels
 * - No hardcoded defaults stored in code
 * - Secure credential storage recommendations
 *
 * @module v3/security/credential-generator
 */

import { randomBytes, randomUUID } from 'crypto';

export interface CredentialConfig {
  /**
   * Length of generated passwords.
   * Default: 32 characters
   */
  passwordLength?: number;

  /**
   * Length of generated API keys.
   * Default: 48 characters
   */
  apiKeyLength?: number;

  /**
   * Length of generated secrets (JWT, session, etc.).
   * Default: 64 characters
   */
  secretLength?: number;

  /**
   * Character set for password generation.
   * Default: alphanumeric + special
   */
  passwordCharset?: string;

  /**
   * Character set for API key generation.
   * Default: alphanumeric only (URL-safe)
   */
  apiKeyCharset?: string;
}

export interface GeneratedCredentials {
  adminPassword: string;
  servicePassword: string;
  jwtSecret: string;
  sessionSecret: string;
  encryptionKey: string;
  generatedAt: Date;
  expiresAt?: Date;
}

export interface ApiKeyCredential {
  key: string;
  prefix: string;
  keyId: string;
  createdAt: Date;
}

export class CredentialGeneratorError extends Error {
  constructor(
    message: string,
    public readonly code: string,
  ) {
    super(message);
    this.name = 'CredentialGeneratorError';
  }
}

/**
 * Character sets for credential generation
 */
const CHARSETS = {
  UPPERCASE: 'ABCDEFGHIJKLMNOPQRSTUVWXYZ',
  LOWERCASE: 'abcdefghijklmnopqrstuvwxyz',
  DIGITS: '0123456789',
  SPECIAL: '!@#$%^&*()_+-=[]{}|;:,.<>?',
  // URL-safe characters for API keys
  URL_SAFE: 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_',
  // Hex characters for secrets
  HEX: '0123456789abcdef',
} as const;

/**
 * Secure credential generator.
 *
 * This class provides cryptographically secure credential generation
 * to replace hardcoded default credentials.
 *
 * @example
 * ```typescript
 * const generator = new CredentialGenerator();
 * const credentials = generator.generateInstallationCredentials();
 * // Store credentials securely (environment variables, secrets manager)
 * ```
 */
export class CredentialGenerator {
  private readonly config: Required<CredentialConfig>;

  constructor(config: CredentialConfig = {}) {
    this.config = {
      passwordLength: config.passwordLength ?? 32,
      apiKeyLength: config.apiKeyLength ?? 48,
      secretLength: config.secretLength ?? 64,
      passwordCharset: config.passwordCharset ??
        CHARSETS.UPPERCASE + CHARSETS.LOWERCASE + CHARSETS.DIGITS + CHARSETS.SPECIAL,
      apiKeyCharset: config.apiKeyCharset ?? CHARSETS.URL_SAFE,
    };

    this.validateConfig();
  }

  /**
   * Validates configuration parameters.
   */
  private validateConfig(): void {
    if (this.config.passwordLength < 16) {
      throw new CredentialGeneratorError(
        'Password length must be at least 16 characters',
        'INVALID_PASSWORD_LENGTH'
      );
    }

    if (this.config.apiKeyLength < 32) {
      throw new CredentialGeneratorError(
        'API key length must be at least 32 characters',
        'INVALID_API_KEY_LENGTH'
      );
    }

    if (this.config.secretLength < 32) {
      throw new CredentialGeneratorError(
        'Secret length must be at least 32 characters',
        'INVALID_SECRET_LENGTH'
      );
    }
  }

  /**
   * Generates a cryptographically secure random string using rejection sampling
   * to eliminate modulo bias.
   *
   * @param length - Length of the string to generate
   * @param charset - Character set to use
   * @returns Random string
   */
  private generateSecureString(length: number, charset: string): string {
    const charsetLength = charset.length;
    const result = new Array(length);

    // Calculate rejection threshold to eliminate modulo bias
    // For a byte (0-255), we reject values >= (256 - (256 % charsetLength))
    // This ensures uniform distribution over charset indices
    const maxValidValue = 256 - (256 % charsetLength);

    let i = 0;
    while (i < length) {
      // Generate more random bytes than needed to reduce iterations
      const randomBuffer = randomBytes(Math.max(length - i, 16));

      for (let j = 0; j < randomBuffer.length && i < length; j++) {
        const randomValue = randomBuffer[j];

        // Rejection sampling: only accept values below threshold
        if (randomValue < maxValidValue) {
          result[i] = charset[randomValue % charsetLength];
          i++;
        }
        // Values >= maxValidValue are rejected to avoid bias
      }
    }

    return result.join('');
  }

  /**
   * Generates a secure random password.
   *
   * @param length - Optional custom length (default from config)
   * @returns Secure random password
   */
  generatePassword(length?: number): string {
    const len = length ?? this.config.passwordLength;

    // Ensure password contains at least one of each required character type
    const password = this.generateSecureString(len, this.config.passwordCharset);

    // Validate the generated password meets requirements
    if (!this.hasRequiredCharacterTypes(password)) {
      // Regenerate if requirements not met (rare case)
      return this.generatePassword(length);
    }

    return password;
  }

  /**
   * Checks if password has required character types.
   */
  private hasRequiredCharacterTypes(password: string): boolean {
    const hasUppercase = /[A-Z]/.test(password);
    const hasLowercase = /[a-z]/.test(password);
    const hasDigit = /\d/.test(password);
    const hasSpecial = /[!@#$%^&*()_+\-=\[\]{}|;:,.<>?]/.test(password);

    return hasUppercase && hasLowercase && hasDigit && hasSpecial;
  }

  /**
   * Generates a secure API key.
   *
   * @param prefix - Optional prefix for the key (e.g., 'cf_')
   * @returns API key credential with metadata
   */
  generateApiKey(prefix = 'cf_'): ApiKeyCredential {
    const keyBody = this.generateSecureString(
      this.config.apiKeyLength - prefix.length,
      this.config.apiKeyCharset
    );

    const key = `${prefix}${keyBody}`;
    const keyId = randomUUID();

    return {
      key,
      prefix,
      keyId,
      createdAt: new Date(),
    };
  }

  /**
   * Generates a secure secret for JWT, sessions, etc.
   *
   * @param length - Optional custom length (default from config)
   * @returns Hex-encoded secret
   */
  generateSecret(length?: number): string {
    const len = length ?? this.config.secretLength;
    // Generate raw bytes and encode as hex for consistent storage
    return randomBytes(Math.ceil(len / 2)).toString('hex').slice(0, len);
  }

  /**
   * Generates an encryption key suitable for AES-256.
   *
   * @returns 32-byte key encoded as hex (64 characters)
   */
  generateEncryptionKey(): string {
    return randomBytes(32).toString('hex');
  }

  /**
   * Generates a complete set of installation credentials.
   *
   * These should be stored securely (environment variables,
   * secrets manager, etc.) and NEVER committed to version control.
   *
   * @param expirationDays - Optional expiration period in days
   * @returns Complete credential set
   */
  generateInstallationCredentials(expirationDays?: number): GeneratedCredentials {
    const now = new Date();
    const expiresAt = expirationDays
      ? new Date(now.getTime() + expirationDays * 24 * 60 * 60 * 1000)
      : undefined;

    return {
      adminPassword: this.generatePassword(),
      servicePassword: this.generatePassword(),
      jwtSecret: this.generateSecret(64),
      sessionSecret: this.generateSecret(64),
      encryptionKey: this.generateEncryptionKey(),
      generatedAt: now,
      expiresAt,
    };
  }

  /**
   * Generates a secure session token.
   *
   * @returns URL-safe session token
   */
  generateSessionToken(): string {
    return this.generateSecureString(64, CHARSETS.URL_SAFE);
  }

  /**
   * Generates a secure CSRF token.
   *
   * @returns CSRF token
   */
  generateCsrfToken(): string {
    return randomBytes(32).toString('base64url');
  }

  /**
   * Generates a secure nonce for one-time use.
   *
   * @returns Unique nonce value
   */
  generateNonce(): string {
    return randomBytes(16).toString('hex');
  }

  /**
   * Creates a setup script output for secure credential deployment.
   *
   * @param credentials - Generated credentials
   * @returns Environment variable export script
   */
  createEnvScript(credentials: GeneratedCredentials): string {
    return `# Claude Flow V3 - Generated Credentials
# Generated: ${credentials.generatedAt.toISOString()}
# IMPORTANT: Store these securely and delete this file after use

export CLAUDE_FLOW_ADMIN_PASSWORD="${credentials.adminPassword}"
export CLAUDE_FLOW_SERVICE_PASSWORD="${credentials.servicePassword}"
export CLAUDE_FLOW_JWT_SECRET="${credentials.jwtSecret}"
export CLAUDE_FLOW_SESSION_SECRET="${credentials.sessionSecret}"
export CLAUDE_FLOW_ENCRYPTION_KEY="${credentials.encryptionKey}"
`;
  }

  /**
   * Creates a JSON configuration output for secure credential deployment.
   *
   * @param credentials - Generated credentials
   * @returns JSON configuration (for secrets manager import)
   */
  createJsonConfig(credentials: GeneratedCredentials): string {
    return JSON.stringify({
      'claude-flow/admin-password': credentials.adminPassword,
      'claude-flow/service-password': credentials.servicePassword,
      'claude-flow/jwt-secret': credentials.jwtSecret,
      'claude-flow/session-secret': credentials.sessionSecret,
      'claude-flow/encryption-key': credentials.encryptionKey,
      'claude-flow/generated-at': credentials.generatedAt.toISOString(),
      'claude-flow/expires-at': credentials.expiresAt?.toISOString() ?? null,
    }, null, 2);
  }
}

/**
 * Factory function to create a production credential generator.
 *
 * @returns Configured CredentialGenerator instance
 */
export function createCredentialGenerator(): CredentialGenerator {
  return new CredentialGenerator();
}

/**
 * Quick credential generation for CLI usage.
 *
 * @returns Generated installation credentials
 */
export function generateCredentials(): GeneratedCredentials {
  const generator = new CredentialGenerator();
  return generator.generateInstallationCredentials();
}

/**
 * Security Context Entity - Domain Layer
 *
 * Represents security context for operations with validation and policy enforcement.
 *
 * @module v3/security/domain/entities
 */

import { randomUUID } from 'crypto';

/**
 * Permission levels
 */
export type PermissionLevel = 'read' | 'write' | 'execute' | 'admin';

/**
 * Security context properties
 */
export interface SecurityContextProps {
  id?: string;
  principalId: string;
  principalType: 'agent' | 'user' | 'system';
  permissions: PermissionLevel[];
  allowedPaths?: string[];
  blockedPaths?: string[];
  allowedCommands?: string[];
  blockedCommands?: string[];
  metadata?: Record<string, unknown>;
  expiresAt?: Date;
  createdAt?: Date;
}

/**
 * Security Context - Entity
 */
export class SecurityContext {
  private _id: string;
  private _principalId: string;
  private _principalType: 'agent' | 'user' | 'system';
  private _permissions: Set<PermissionLevel>;
  private _allowedPaths: Set<string>;
  private _blockedPaths: Set<string>;
  private _allowedCommands: Set<string>;
  private _blockedCommands: Set<string>;
  private _metadata: Record<string, unknown>;
  private _expiresAt?: Date;
  private _createdAt: Date;

  private constructor(props: SecurityContextProps) {
    this._id = props.id ?? randomUUID();
    this._principalId = props.principalId;
    this._principalType = props.principalType;
    this._permissions = new Set(props.permissions);
    this._allowedPaths = new Set(props.allowedPaths ?? []);
    this._blockedPaths = new Set(props.blockedPaths ?? []);
    this._allowedCommands = new Set(props.allowedCommands ?? []);
    this._blockedCommands = new Set(props.blockedCommands ?? []);
    this._metadata = props.metadata ?? {};
    this._expiresAt = props.expiresAt;
    this._createdAt = props.createdAt ?? new Date();
  }

  static create(props: SecurityContextProps): SecurityContext {
    return new SecurityContext(props);
  }

  static fromPersistence(props: SecurityContextProps): SecurityContext {
    return new SecurityContext(props);
  }

  get id(): string { return this._id; }
  get principalId(): string { return this._principalId; }
  get principalType(): string { return this._principalType; }
  get permissions(): PermissionLevel[] { return Array.from(this._permissions); }
  get allowedPaths(): string[] { return Array.from(this._allowedPaths); }
  get blockedPaths(): string[] { return Array.from(this._blockedPaths); }
  get allowedCommands(): string[] { return Array.from(this._allowedCommands); }
  get blockedCommands(): string[] { return Array.from(this._blockedCommands); }
  get metadata(): Record<string, unknown> { return { ...this._metadata }; }
  get expiresAt(): Date | undefined { return this._expiresAt; }
  get createdAt(): Date { return new Date(this._createdAt); }

  // Business Logic

  hasPermission(level: PermissionLevel): boolean {
    return this._permissions.has(level) || this._permissions.has('admin');
  }

  isExpired(): boolean {
    if (!this._expiresAt) return false;
    return Date.now() > this._expiresAt.getTime();
  }

  canAccessPath(path: string): boolean {
    if (this.isExpired()) return false;

    // Check blocked paths first
    for (const blocked of this._blockedPaths) {
      if (path.startsWith(blocked) || this.matchGlob(path, blocked)) {
        return false;
      }
    }

    // If no allowed paths specified, allow all non-blocked
    if (this._allowedPaths.size === 0) return true;

    // Check allowed paths
    for (const allowed of this._allowedPaths) {
      if (path.startsWith(allowed) || this.matchGlob(path, allowed)) {
        return true;
      }
    }

    return false;
  }

  canExecuteCommand(command: string): boolean {
    if (this.isExpired()) return false;

    const cmdBase = command.split(' ')[0];

    // Check blocked commands first
    if (this._blockedCommands.has(cmdBase) || this._blockedCommands.has(command)) {
      return false;
    }

    // If no allowed commands specified, allow all non-blocked
    if (this._allowedCommands.size === 0) return true;

    // Check allowed commands
    return this._allowedCommands.has(cmdBase) || this._allowedCommands.has(command);
  }

  private matchGlob(path: string, pattern: string): boolean {
    const regex = pattern
      .replace(/\*\*/g, '.*')
      .replace(/\*/g, '[^/]*')
      .replace(/\?/g, '.');
    return new RegExp(`^${regex}$`).test(path);
  }

  grantPermission(level: PermissionLevel): void {
    this._permissions.add(level);
  }

  revokePermission(level: PermissionLevel): void {
    this._permissions.delete(level);
  }

  addAllowedPath(path: string): void {
    this._allowedPaths.add(path);
  }

  addBlockedPath(path: string): void {
    this._blockedPaths.add(path);
  }

  toPersistence(): Record<string, unknown> {
    return {
      id: this._id,
      principalId: this._principalId,
      principalType: this._principalType,
      permissions: Array.from(this._permissions),
      allowedPaths: Array.from(this._allowedPaths),
      blockedPaths: Array.from(this._blockedPaths),
      allowedCommands: Array.from(this._allowedCommands),
      blockedCommands: Array.from(this._blockedCommands),
      metadata: this._metadata,
      expiresAt: this._expiresAt?.toISOString(),
      createdAt: this._createdAt.toISOString(),
    };
  }
}

/**
 * Security Domain Layer - Public Exports
 *
 * @module v3/security/domain
 */

export {
  SecurityContext,
  type PermissionLevel,
  type SecurityContextProps,
} from './entities/security-context.js';

export {
  SecurityDomainService,
  type ValidationResult,
  type ThreatDetectionResult,
} from './services/security-domain-service.js';

/**
 * Security Domain Service - Domain Layer
 *
 * Contains security logic for validation, policy enforcement, and threat detection.
 *
 * @module v3/security/domain/services
 */

import { SecurityContext, PermissionLevel } from '../entities/security-context.js';

/**
 * Validation result
 */
export interface ValidationResult {
  valid: boolean;
  errors: string[];
  warnings: string[];
  sanitized?: string;
}

/**
 * Threat detection result
 */
export interface ThreatDetectionResult {
  safe: boolean;
  threats: Array<{
    type: string;
    severity: 'low' | 'medium' | 'high' | 'critical';
    description: string;
    location?: string;
  }>;
}

/**
 * Security Domain Service
 */
export class SecurityDomainService {
  // Dangerous patterns for path traversal
  private static readonly PATH_TRAVERSAL_PATTERNS = [
    /\.\./,
    /~\//,
    /^\/etc\//,
    /^\/tmp\//,
    /^\/var\/log\//,
    /^C:\\Windows/i,
    /^C:\\Users\\[^\\]+\\AppData/i,
  ];

  // Dangerous command patterns
  private static readonly DANGEROUS_COMMANDS = [
    /^rm\s+-rf\s+\//,
    /^rm\s+-rf\s+\*/,
    /^dd\s+if=/,
    /^mkfs\./,
    /^format\s+/i,
    /^del\s+\/s\s+\/q/i,
    />\s*\/dev\/sd[a-z]/,
    /\|\s*bash$/,
    /\|\s*sh$/,
    /eval\s*\(/,
    /exec\s*\(/,
  ];

  // SQL injection patterns
  private static readonly SQL_INJECTION_PATTERNS = [
    /'\s*OR\s+'1'\s*=\s*'1/i,
    /'\s*OR\s+1\s*=\s*1/i,
    /;\s*DROP\s+TABLE/i,
    /;\s*DELETE\s+FROM/i,
    /UNION\s+SELECT/i,
    /--\s*$/,
  ];

  // XSS patterns
  private static readonly XSS_PATTERNS = [
    /<script[\s>]/i,
    /javascript:/i,
    /on\w+\s*=/i,
    /<iframe/i,
    /<object/i,
    /<embed/i,
  ];

  /**
   * Validate a file path
   */
  validatePath(path: string, context: SecurityContext): ValidationResult {
    const errors: string[] = [];
    const warnings: string[] = [];

    // Check path traversal
    for (const pattern of SecurityDomainService.PATH_TRAVERSAL_PATTERNS) {
      if (pattern.test(path)) {
        errors.push(`Path traversal detected: ${pattern.source}`);
      }
    }

    // Check context permissions
    if (!context.canAccessPath(path)) {
      errors.push(`Access denied to path: ${path}`);
    }

    // Check for suspicious paths
    if (path.includes('..')) {
      warnings.push('Path contains parent directory reference');
    }

    return {
      valid: errors.length === 0,
      errors,
      warnings,
      sanitized: this.sanitizePath(path),
    };
  }

  /**
   * Validate a command
   */
  validateCommand(command: string, context: SecurityContext): ValidationResult {
    const errors: string[] = [];
    const warnings: string[] = [];

    // Check dangerous commands
    for (const pattern of SecurityDomainService.DANGEROUS_COMMANDS) {
      if (pattern.test(command)) {
        errors.push(`Dangerous command pattern detected: ${pattern.source}`);
      }
    }

    // Check context permissions
    if (!context.canExecuteCommand(command)) {
      errors.push(`Command execution denied: ${command}`);
    }

    if (!context.hasPermission('execute')) {
      errors.push('Execute permission required');
    }

    // Check for shell injection
    if (/[;&|`$(){}]/.test(command)) {
      warnings.push('Command contains shell metacharacters');
    }

    return {
      valid: errors.length === 0,
      errors,
      warnings,
      sanitized: this.sanitizeCommand(command),
    };
  }

  /**
   * Validate user input
   */
  validateInput(input: string): ValidationResult {
    const errors: string[] = [];
    const warnings: string[] = [];

    // Check for SQL injection
    for (const pattern of SecurityDomainService.SQL_INJECTION_PATTERNS) {
      if (pattern.test(input)) {
        errors.push(`SQL injection pattern detected`);
        break;
      }
    }

    // Check for XSS
    for (const pattern of SecurityDomainService.XSS_PATTERNS) {
      if (pattern.test(input)) {
        errors.push(`XSS pattern detected`);
        break;
      }
    }

    // Check length
    if (input.length > 10000) {
      warnings.push('Input exceeds recommended length');
    }

    return {
      valid: errors.length === 0,
      errors,
      warnings,
      sanitized: this.sanitizeInput(input),
    };
  }

  /**
   * Detect threats in content
   */
  detectThreats(content: string): ThreatDetectionResult {
    const threats: ThreatDetectionResult['threats'] = [];

    // Check for various threat patterns
    if (/<script/i.test(content)) {
      threats.push({
        type: 'xss',
        severity: 'high',
        description: 'Script tag detected',
      });
    }

    if (/password\s*[:=]\s*["'][^"']+["']/i.test(content)) {
      threats.push({
        type: 'credential-exposure',
        severity: 'critical',
        description: 'Hardcoded password detected',
      });
    }

    if (/api[_-]?key\s*[:=]\s*["'][^"']+["']/i.test(content)) {
      threats.push({
        type: 'credential-exposure',
        severity: 'critical',
        description: 'API key detected',
      });
    }

    if (/eval\s*\(/.test(content)) {
      threats.push({
        type: 'code-injection',
        severity: 'high',
        description: 'Eval statement detected',
      });
    }

    return {
      safe: threats.length === 0,
      threats,
    };
  }

  /**
   * Sanitize path
   */
  private sanitizePath(path: string): string {
    return path
      .replace(/\.\./g, '')
      .replace(/\/\//g, '/')
      .replace(/^~\//, '')
      .trim();
  }

  /**
   * Sanitize command
   */
  private sanitizeCommand(command: string): string {
    return command
      .replace(/[;&|`$]/g, '')
      .replace(/\$\([^)]*\)/g, '')
      .trim();
  }

  /**
   * Sanitize user input
   */
  private sanitizeInput(input: string): string {
    return input
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#x27;')
      .replace(/\//g, '&#x2F;');
  }

  /**
   * Create security context for agent
   */
  createAgentContext(
    agentId: string,
    role: string,
    customPaths?: string[]
  ): SecurityContext {
    // Default permissions based on role
    const rolePermissions: Record<string, PermissionLevel[]> = {
      'queen-coordinator': ['read', 'write', 'execute', 'admin'],
      'security-architect': ['read', 'write', 'execute', 'admin'],
      'coder': ['read', 'write', 'execute'],
      'reviewer': ['read'],
      'tester': ['read', 'execute'],
      default: ['read'],
    };

    const permissions = rolePermissions[role] ?? rolePermissions.default;

    return SecurityContext.create({
      principalId: agentId,
      principalType: 'agent',
      permissions,
      allowedPaths: customPaths ?? ['./src', './tests', './docs'],
      blockedPaths: ['/etc', '/var', '~/', '../'],
      allowedCommands: ['npm', 'node', 'git', 'vitest'],
      blockedCommands: ['rm -rf /', 'dd', 'mkfs', 'format'],
    });
  }
}

/**
 * V3 Security Module
 *
