const DEFAULT_TIMEOUT_MS = 5 * 60 * 1000; // 5 minutes, matches meta-proxy's CALLBACK_TIMEOUT

export class CallbackTimeoutError extends Error {
  constructor() {
    super('timed out waiting for OAuth callback');
    this.name = 'CallbackTimeoutError';
  }
}

export class CallbackServer {
  private constructor(
    private readonly server: Server,
    public readonly redirectUri: string,
    public readonly port: number,
  ) {}

  /**
   * Binds `127.0.0.1:0` (OS-assigned ephemeral port) and returns the server
   * plus the exact `redirect_uri` to send in the authorize request — must be
   * the `http://127.0.0.1:<port>/oauth/callback` shape identity's
   * `validate_redirect_uri` accepts.
   */
  static async bind(): Promise<CallbackServer> {
    return new Promise((resolve, reject) => {
      const server = createServer();
      server.once('error', reject);
      server.listen(0, '127.0.0.1', () => {
        server.removeListener('error', reject);
        const addr = server.address() as AddressInfo;
        const redirectUri = `http://127.0.0.1:${addr.port}/oauth/callback`;
        resolve(new CallbackServer(server, redirectUri, addr.port));
      });
    });
  }

  /**
   * Waits for exactly one `GET /oauth/callback?...` request, replies with the
   * browser success page, closes the server, and returns the parsed query
   * parameters. Times out after `waitForMs` so a login attempt the user
   * abandons in the browser doesn't hang the CLI forever.
   */
  async awaitCallback(waitForMs = DEFAULT_TIMEOUT_MS): Promise<CallbackResult> {
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        this.server.close();
        reject(new CallbackTimeoutError());
      }, waitForMs);

      this.server.once('request', (req, res) => {
        clearTimeout(timer);
        const url = new URL(req.url ?? '/oauth/callback', 'http://127.0.0.1');
        const result: CallbackResult = {
          code: url.searchParams.get('code'),
          state: url.searchParams.get('state'),
          error: url.searchParams.get('error'),
        };
        res.writeHead(200, {
          'content-type': 'text/html; charset=utf-8',
          connection: 'close',
        });
        res.end(SUCCESS_PAGE, () => {
          this.server.close();
          resolve(result);
        });
      });
    });
  }
}

/**
 * HTTP client for `auth.cognitum.one`'s OAuth surface (ADR-306): authorize
 * URL construction, `POST /oauth/token` (`authorization_code` and
 * `refresh_token` grants), and `POST /v1/oauth/code-exchange` (OOB fallback).
 *
 * A TypeScript port of meta-proxy's `src/oauth/client.rs`
 * (cognitum-one/meta-proxy) — same base URL, same endpoints, same
 * form/query parameter names, confirmed live 2026-07-16 (a real
 * `GET /oauth/authorize?...&client_id=meta-proxy&redirect_uri=<ruflo-controlled
 * loopback>` returns a working consent page, not a redirect_uri-mismatch
 * error — so this client reuses meta-proxy's registered `client_id` rather
 * than requiring a new one).
 *
 * Deliberately NOT `api.cognitum.one/v1/auth/*` — that's what ruflo's own
 * checked-in OpenAPI spec (v3/docs/api/cognitum-v1.openapi.yaml, ADR-308)
 * describes, but it does not match what the real identity server serves.
 * This client targets the proven, live surface instead.
 *
 * @module v3/security/oauth/client
 */

export const CLIENT_ID = 'meta-proxy';
export const SCOPE = 'inference';
/** RFC 8252 out-of-band sentinel — the OOB/manual-paste flow's `redirect_uri`. */
export const OOB_REDIRECT_URI = 'urn:ietf:wg:oauth:2.0:oob';

function authBaseUrl(): string {
  const override = process.env.COGNITUM_AUTH_URL;
  return override && override.trim() ? override : 'https://auth.cognitum.one';
}

export interface TokenResponse {
  access_token: string;
  token_type: string;
  account_email?: string;
  refresh_token?: string;
  expires_in?: number;
}

interface OAuthErrorBody {
  error: string;
  error_description: string;
}

export class OAuthError extends Error {
  constructor(
    message: string,
    public readonly code: 'network' | 'protocol' | 'unexpected_shape',
    public readonly oauthError?: string,
    public readonly oauthDescription?: string,
  ) {
    super(message);
    this.name = 'OAuthError';
  }
}

/** Builds the `/oauth/authorize` URL for the standard loopback-redirect flow. */
export function authorizeUrl(redirectUri: string, state: string, codeChallenge: string): string {
  const url = new URL(`${authBaseUrl()}/oauth/authorize`);
  url.searchParams.set('response_type', 'code');
  url.searchParams.set('client_id', CLIENT_ID);
  url.searchParams.set('redirect_uri', redirectUri);
  url.searchParams.set('scope', SCOPE);
  url.searchParams.set('state', state);
  url.searchParams.set('code_challenge', codeChallenge);
  url.searchParams.set('code_challenge_method', 'S256');
  return url.toString();
}

async function parseTokenResponse(resp: Response): Promise<TokenResponse> {
  if (resp.ok) {
    try {
      return (await resp.json()) as TokenResponse;
    } catch {
      throw new OAuthError('unexpected response shape from the server', 'unexpected_shape');
    }
  }
  try {
    const body = (await resp.json()) as OAuthErrorBody;
    throw new OAuthError(
      `oauth error: ${body.error} — ${body.error_description}`,
      'protocol',
      body.error,
      body.error_description,
    );
  } catch (e) {
    if (e instanceof OAuthError) throw e;
    throw new OAuthError('unexpected response shape from the server', 'unexpected_shape');
  }
}

async function postForm(path: string, form: Record<string, string>, base = authBaseUrl()): Promise<TokenResponse> {
  let resp: Response;
  try {
    resp = await fetch(`${base}${path}`, {
      method: 'POST',
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams(form).toString(),
    });
  } catch (e) {
    throw new OAuthError(`network error: ${e instanceof Error ? e.message : String(e)}`, 'network');
  }
  return parseTokenResponse(resp);
}

/** `POST /oauth/token` with `grant_type=authorization_code`. */
export async function exchangeCode(
  code: string,
  codeVerifier: string,
  redirectUri: string,
  base = authBaseUrl(),
): Promise<TokenResponse> {
  return postForm(
    '/oauth/token',
    { grant_type: 'authorization_code', code, code_verifier: codeVerifier, client_id: CLIENT_ID, redirect_uri: redirectUri },
    base,
  );
}

/**
 * `POST /oauth/token` with `grant_type=refresh_token`. identity rotates
 * refresh tokens with reuse detection: presenting a refresh token returns a
 * NEW refresh token and revokes the old one, and re-presenting a spent one
 * revokes the whole session family. Callers MUST persist the returned
 * `refresh_token` atomically before using the new access token, and must
 * never retry a failed refresh with the same token.
 */
export async function refreshToken(refreshTokenValue: string, base = authBaseUrl()): Promise<TokenResponse> {
  return postForm('/oauth/token', { grant_type: 'refresh_token', refresh_token: refreshTokenValue, client_id: CLIENT_ID }, base);
}

/**
 * `POST /v1/oauth/code-exchange` — the OOB manual-entry fallback for
 * headless/SSH/container environments where no browser round-trip to
 * `127.0.0.1` is reachable.
 */
export async function exchangeManualCode(
  code: string,
  codeVerifier: string,
  base = authBaseUrl(),
): Promise<TokenResponse> {
  let resp: Response;
  try {
    resp = await fetch(`${base}/v1/oauth/code-exchange`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ code, code_verifier: codeVerifier, client_id: CLIENT_ID }),
    });
  } catch (e) {
    throw new OAuthError(`network error: ${e instanceof Error ? e.message : String(e)}`, 'network');
  }
  return parseTokenResponse(resp);
}

/**
 * OAuth 2.0 + PKCE (RFC 7636) client-side generation (ADR-306).
 *
 * A TypeScript port of meta-proxy's `src/oauth/pkce.rs` (cognitum-one/meta-proxy,
 * itself ported from `dashboard/apps/cli/src/pkce.rs`) so a verifier generated
 * here validates against the same `services/identity` authorization server
 * meta-proxy already talks to successfully — same byte lengths, same encoding,
 * same hash. Intentionally duplicated rather than imported from
 * `@claude-flow/mcp/src/oauth.ts` (a different, unrelated OAuth client in this
 * monorepo) — ADR-306 assigns PKCE ownership to this package specifically.
 *
 * @module v3/security/oauth/pkce
 */

import { randomBytes, createHash } from 'crypto';

export interface PkceRequest {
  state: string;
  codeVerifier: string;
  codeChallenge: string;
}

/**
 * 32 random bytes, base64url-encoded (no padding) — comfortably within RFC
 * 7636's 43-128 character verifier length requirement (32 bytes -> 43 chars).
 * Matches the Rust port's `random_url_safe_token(32)` exactly.
 */
function randomUrlSafeToken(byteLen: number): string {
  return randomBytes(byteLen).toString('base64url');
}

export function challengeFromVerifier(verifier: string): string {
  return createHash('sha256').update(verifier).digest('base64url');
}

/**
 * Generates a fresh `state` + PKCE verifier/challenge pair for one login
 * attempt.
 */
export function generate(): PkceRequest {
  const state = randomUrlSafeToken(32);
  const codeVerifier = randomUrlSafeToken(32);
  const codeChallenge = challengeFromVerifier(codeVerifier);
  return { state, codeVerifier, codeChallenge };
}

/**
 * Password Hasher - CVE-2 Remediation
 *
 * Fixes weak password hashing by replacing SHA-256 with hardcoded salt
 * with bcrypt using 12 rounds (configurable).
 *
 * Security Properties:
 * - bcrypt with adaptive cost factor (12 rounds)
 * - Automatic salt generation per password
 * - Timing-safe comparison
 * - Minimum password length enforcement
 *
 * @module v3/security/password-hasher
 */

// #1608 — switched from `bcrypt` to `bcryptjs` to drop the
// `@mapbox/node-pre-gyp → tar <=7.5.10` transitive chain that pulled in
// 6 HIGH-severity CVEs (GHSA-34x7-hfp2-rc4v, GHSA-8qq5-rm4j-mr97, etc.).
// `bcryptjs` is a pure-JS implementation that produces the same `$2a$` /
// `$2b$` hash format and exposes the same `hash()` / `compare()` API
// surface this module uses, so the swap is transparent to callers and to
// any persisted hashes.
import * as bcrypt from 'bcryptjs';

export interface PasswordHasherConfig {
  /**
   * Number of bcrypt rounds (cost factor).
   * Default: 12 (recommended minimum for production)
   * Each increment doubles the computation time.
   */
  rounds?: number;

  /**
   * Minimum password length.
   * Default: 8 characters
   */
  minLength?: number;

  /**
   * Maximum password length.
   * Default: 128 characters (bcrypt limit is 72 bytes)
   */
  maxLength?: number;

  /**
   * Require at least one uppercase letter.
   * Default: true
   */
  requireUppercase?: boolean;

  /**
   * Require at least one lowercase letter.
   * Default: true
   */
  requireLowercase?: boolean;

  /**
   * Require at least one digit.
   * Default: true
   */
  requireDigit?: boolean;

  /**
   * Require at least one special character.
   * Default: false
   */
  requireSpecial?: boolean;
}

export interface PasswordValidationResult {
  isValid: boolean;
  errors: string[];
}

export class PasswordHashError extends Error {
  constructor(
    message: string,
    public readonly code: string,
  ) {
    super(message);
    this.name = 'PasswordHashError';
  }
}

/**
 * Secure password hasher using bcrypt.
 *
 * This class replaces the vulnerable SHA-256 + hardcoded salt implementation
 * with industry-standard bcrypt hashing.
 *
 * @example
 * ```typescript
 * const hasher = new PasswordHasher({ rounds: 12 });
 * const hash = await hasher.hash('securePassword123');
 * const isValid = await hasher.verify('securePassword123', hash);
 * ```
 */
export class PasswordHasher {
  private readonly config: Required<PasswordHasherConfig>;

  constructor(config: PasswordHasherConfig = {}) {
    this.config = {
      rounds: config.rounds ?? 12,
      minLength: config.minLength ?? 8,
      maxLength: config.maxLength ?? 128,
      requireUppercase: config.requireUppercase ?? true,
      requireLowercase: config.requireLowercase ?? true,
      requireDigit: config.requireDigit ?? true,
      requireSpecial: config.requireSpecial ?? false,
    };

    // Validate configuration
    if (this.config.rounds < 10 || this.config.rounds > 20) {
      throw new PasswordHashError(
        'Bcrypt rounds must be between 10 and 20 for security and performance balance',
        'INVALID_ROUNDS'
      );
    }

    if (this.config.minLength < 8) {
      throw new PasswordHashError(
        'Minimum password length must be at least 8 characters',
        'INVALID_MIN_LENGTH'
      );
    }
  }

  /**
   * Validates password against configured requirements.
   *
   * @param password - The password to validate
   * @returns Validation result with errors if any
   */
  validate(password: string): PasswordValidationResult {
    const errors: string[] = [];

    if (!password) {
      errors.push('Password is required');
      return { isValid: false, errors };
    }

    if (password.length < this.config.minLength) {
      errors.push(`Password must be at least ${this.config.minLength} characters`);
    }

    if (password.length > this.config.maxLength) {
      errors.push(`Password must not exceed ${this.config.maxLength} characters`);
    }

    if (this.config.requireUppercase && !/[A-Z]/.test(password)) {
      errors.push('Password must contain at least one uppercase letter');
    }

    if (this.config.requireLowercase && !/[a-z]/.test(password)) {
      errors.push('Password must contain at least one lowercase letter');
    }

    if (this.config.requireDigit && !/\d/.test(password)) {
      errors.push('Password must contain at least one digit');
    }

    if (this.config.requireSpecial && !/[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(password)) {
      errors.push('Password must contain at least one special character');
    }

    return {
      isValid: errors.length === 0,
      errors,
    };
  }

  /**
   * Hashes a password using bcrypt.
   *
   * @param password - The plaintext password to hash
   * @returns The bcrypt hash
   * @throws PasswordHashError if password is invalid
   */
  async hash(password: string): Promise<string> {
    const validation = this.validate(password);

    if (!validation.isValid) {
      throw new PasswordHashError(
        validation.errors.join('; '),
        'VALIDATION_FAILED'
      );
    }

    try {
      // bcrypt automatically generates a random salt per hash
      return await bcrypt.hash(password, this.config.rounds);
    } catch (error) {
      throw new PasswordHashError(
        'Failed to hash password',
        'HASH_FAILED'
      );
    }
  }

  /**
   * Verifies a password against a bcrypt hash.
   * Uses timing-safe comparison internally.
   *
   * @param password - The plaintext password to verify
   * @param hash - The bcrypt hash to compare against
   * @returns True if password matches, false otherwise
   */
  async verify(password: string, hash: string): Promise<boolean> {
    if (!password || !hash) {
      return false;
    }

    // Validate hash format (bcrypt hashes start with $2a$, $2b$, or $2y$)
    if (!this.isValidBcryptHash(hash)) {
      return false;
    }

    try {
      // bcrypt.compare uses timing-safe comparison
      return await bcrypt.compare(password, hash);
    } catch (error) {
      // Return false on any error to prevent timing attacks
      return false;
    }
  }

  /**
   * Checks if a hash needs to be rehashed with updated parameters.
   * Useful for upgrading hash strength over time.
   *
   * @param hash - The bcrypt hash to check
   * @returns True if hash should be updated
   */
  needsRehash(hash: string): boolean {
    if (!this.isValidBcryptHash(hash)) {
      return true;
    }

    // Extract rounds from hash (format: $2b$XX$...)
    const match = hash.match(/^\$2[aby]\$(\d{2})\$/);
    if (!match) {
      return true;
    }

    const hashRounds = parseInt(match[1], 10);
    return hashRounds < this.config.rounds;
  }

  /**
   * Validates bcrypt hash format.
   *
   * @param hash - The hash to validate
   * @returns True if valid bcrypt hash format
   */
  private isValidBcryptHash(hash: string): boolean {
    // bcrypt hash format: $2a$XX$22charsSalt31charsHash
    // Total length: 60 characters
    return /^\$2[aby]\$\d{2}\$[./A-Za-z0-9]{53}$/.test(hash);
  }

  /**
   * Returns current configuration (without sensitive defaults).
   */
  getConfig(): Readonly<Omit<Required<PasswordHasherConfig>, never>> {
    return { ...this.config };
  }
}

/**
 * Factory function to create a production-ready password hasher.
 *
 * @param rounds - Bcrypt rounds (default: 12)
 * @returns Configured PasswordHasher instance
 */
export function createPasswordHasher(rounds = 12): PasswordHasher {
  return new PasswordHasher({ rounds });
}

/**
 * Path Validator - HIGH-2 Remediation
 *
 * Fixes path traversal vulnerabilities by:
 * - Validating all file paths against allowed prefixes
 * - Using path.resolve() for canonicalization
 * - Blocking traversal patterns (../, etc.)
 * - Enforcing path length limits
 *
 * Security Properties:
 * - Path canonicalization
 * - Prefix validation
 * - Symlink resolution (optional)
 * - Traversal pattern detection
 *
 * @module v3/security/path-validator
 */

import * as path from 'path';
import * as fs from 'fs/promises';

export interface PathValidatorConfig {
  /**
   * Allowed directory prefixes.
   * Paths must start with one of these after resolution.
   */
  allowedPrefixes: string[];

  /**
   * Blocked file extensions.
   * Files with these extensions are rejected.
   */
  blockedExtensions?: string[];

  /**
   * Blocked file names.
   * Files matching these names are rejected.
   */
  blockedNames?: string[];

  /**
   * Maximum path length.
   * Default: 4096 characters
   */
  maxPathLength?: number;

  /**
   * Whether to resolve symlinks.
   * Default: true
   */
  resolveSymlinks?: boolean;

  /**
   * Whether to allow paths that don't exist.
   * Default: true (for write operations)
   */
  allowNonExistent?: boolean;

  /**
   * Whether to allow hidden files/directories.
   * Default: false
   */
  allowHidden?: boolean;
}

export interface PathValidationResult {
  isValid: boolean;
  resolvedPath: string;
  relativePath: string;
  matchedPrefix: string;
  errors: string[];
}

export class PathValidatorError extends Error {
  constructor(
    message: string,
    public readonly code: string,
    public readonly path?: string,
  ) {
    super(message);
    this.name = 'PathValidatorError';
  }
}

/**
 * Dangerous path patterns that indicate traversal attempts.
 */
const TRAVERSAL_PATTERNS = [
  /\.\.\//,              // ../
  /\.\.\\/,              // ..\
  /\.\./,                // .. anywhere
  /%2e%2e/i,             // URL-encoded ..
  /%252e%252e/i,         // Double URL-encoded ..
  /\.%2e/i,              // Mixed encoding
  /%2e\./i,              // Mixed encoding
  /\0/,                  // Null byte
  /%00/,                 // URL-encoded null
];

/**
 * Default blocked file extensions (sensitive files).
 */
const DEFAULT_BLOCKED_EXTENSIONS = [
  '.env',
  '.pem',
  '.key',
  '.crt',
  '.pfx',
  '.p12',
  '.jks',
  '.keystore',
  '.secret',
  '.credentials',
];

/**
 * Default blocked file names (sensitive files).
 */
const DEFAULT_BLOCKED_NAMES = [
  'id_rsa',
  'id_dsa',
  'id_ecdsa',
  'id_ed25519',
  '.htpasswd',
  '.htaccess',
  'shadow',
  'passwd',
  'authorized_keys',
  'known_hosts',
  '.git',
  '.gitconfig',
  '.npmrc',
  '.docker',
];

/**
 * Path validator that prevents traversal attacks.
 *
 * This class validates file paths to ensure they stay within
 * allowed directories and don't access sensitive files.
 *
 * @example
 * ```typescript
 * const validator = new PathValidator({
 *   allowedPrefixes: ['/workspaces/project']
 * });
 *
 * const result = await validator.validate('/workspaces/project/src/file.ts');
 * if (result.isValid) {
 *   // Safe to use result.resolvedPath
 * }
 * ```
 */
export class PathValidator {
  private readonly config: Required<PathValidatorConfig>;
  private readonly resolvedPrefixes: string[];

  constructor(config: PathValidatorConfig) {
    this.config = {
      allowedPrefixes: config.allowedPrefixes,
      blockedExtensions: config.blockedExtensions ?? DEFAULT_BLOCKED_EXTENSIONS,
      blockedNames: config.blockedNames ?? DEFAULT_BLOCKED_NAMES,
      maxPathLength: config.maxPathLength ?? 4096,
      resolveSymlinks: config.resolveSymlinks ?? true,
      allowNonExistent: config.allowNonExistent ?? true,
      allowHidden: config.allowHidden ?? false,
    };

    if (this.config.allowedPrefixes.length === 0) {
      throw new PathValidatorError(
        'At least one allowed prefix must be specified',
        'EMPTY_PREFIXES'
      );
    }

    // Pre-resolve all prefixes
    this.resolvedPrefixes = this.config.allowedPrefixes.map(p =>
      path.resolve(p)
    );
  }

  /**
   * Validates a path against security rules.
   *
   * @param inputPath - The path to validate
   * @returns Validation result with resolved path
   */
  async validate(inputPath: string): Promise<PathValidationResult> {
    const errors: string[] = [];

    // Check for empty path
    if (!inputPath || inputPath.trim() === '') {
      return {
        isValid: false,
        resolvedPath: '',
        relativePath: '',
        matchedPrefix: '',
        errors: ['Path is empty'],
      };
    }

    // Check path length
    if (inputPath.length > this.config.maxPathLength) {
      return {
        isValid: false,
        resolvedPath: '',
        relativePath: '',
        matchedPrefix: '',
        errors: [`Path exceeds maximum length of ${this.config.maxPathLength}`],
      };
    }

    // Check for traversal patterns
    for (const pattern of TRAVERSAL_PATTERNS) {
      if (pattern.test(inputPath)) {
        return {
          isValid: false,
          resolvedPath: '',
          relativePath: '',
          matchedPrefix: '',
          errors: ['Path traversal pattern detected'],
        };
      }
    }

    // Resolve the path
    let resolvedPath: string;
    try {
      resolvedPath = path.resolve(inputPath);

      // Optionally resolve symlinks
      if (this.config.resolveSymlinks) {
        try {
          resolvedPath = await fs.realpath(resolvedPath);
        } catch (error: any) {
          // Path doesn't exist yet - use resolved path
          if (error.code !== 'ENOENT' || !this.config.allowNonExistent) {
            if (error.code === 'ENOENT') {
              errors.push('Path does not exist');
            } else {
              errors.push(`Failed to resolve path: ${error.message}`);
            }
          }
        }
      }
    } catch (error: any) {
      return {
        isValid: false,
        resolvedPath: '',
        relativePath: '',
        matchedPrefix: '',
        errors: [`Invalid path: ${error.message}`],
      };
    }

    // Check against allowed prefixes
    let matchedPrefix = '';
    let relativePath = '';
    let prefixMatched = false;

    for (const prefix of this.resolvedPrefixes) {
      if (resolvedPath === prefix || resolvedPath.startsWith(prefix + path.sep)) {
        prefixMatched = true;
        matchedPrefix = prefix;
        relativePath = resolvedPath.slice(prefix.length);
        if (relativePath.startsWith(path.sep)) {
          relativePath = relativePath.slice(1);
        }
        break;
      }
    }

    if (!prefixMatched) {
      return {
        isValid: false,
        resolvedPath,
        relativePath: '',
        matchedPrefix: '',
        errors: ['Path is outside allowed directories'],
      };
    }

    // Check for hidden files
    const pathParts = resolvedPath.split(path.sep);
    if (!this.config.allowHidden) {
      for (const part of pathParts) {
        if (part.startsWith('.') && part !== '.' && part !== '..') {
          errors.push('Hidden files/directories are not allowed');
          break;
        }
      }
    }

    // Check blocked file names
    const basename = path.basename(resolvedPath);
    if (this.config.blockedNames.includes(basename)) {
      errors.push(`File name "${basename}" is blocked`);
    }

    // Check blocked extensions
    const ext = path.extname(resolvedPath).toLowerCase();
    if (this.config.blockedExtensions.includes(ext)) {
      errors.push(`File extension "${ext}" is blocked`);
    }

    // Also check for double extensions (e.g., .tar.gz, .config.json)
    const fullname = basename.toLowerCase();
    for (const blockedExt of this.config.blockedExtensions) {
      if (fullname.endsWith(blockedExt)) {
        errors.push(`File extension "${blockedExt}" is blocked`);
        break;
      }
    }

    return {
      isValid: errors.length === 0,
      resolvedPath,
      relativePath,
      matchedPrefix,
      errors,
    };
  }

  /**
   * Validates and returns resolved path, throwing on failure.
   *
   * @param inputPath - The path to validate
   * @returns Resolved path if valid
   * @throws PathValidatorError if validation fails
   */
  async validateOrThrow(inputPath: string): Promise<string> {
    const result = await this.validate(inputPath);

    if (!result.isValid) {
      throw new PathValidatorError(
        result.errors.join('; '),
        'VALIDATION_FAILED',
        inputPath
      );
    }

    return result.resolvedPath;
  }

  /**
   * Synchronous validation (without symlink resolution).
   *
   * @param inputPath - The path to validate
   * @returns Validation result
   */
  validateSync(inputPath: string): PathValidationResult {
    const errors: string[] = [];

    if (!inputPath || inputPath.trim() === '') {
      return {
        isValid: false,
        resolvedPath: '',
        relativePath: '',
        matchedPrefix: '',
        errors: ['Path is empty'],
      };
    }

    if (inputPath.length > this.config.maxPathLength) {
      return {
        isValid: false,
        resolvedPath: '',
        relativePath: '',
        matchedPrefix: '',
        errors: [`Path exceeds maximum length of ${this.config.maxPathLength}`],
      };
    }

    for (const pattern of TRAVERSAL_PATTERNS) {
      if (pattern.test(inputPath)) {
        return {
          isValid: false,
          resolvedPath: '',
          relativePath: '',
          matchedPrefix: '',
          errors: ['Path traversal pattern detected'],
        };
      }
    }

    const resolvedPath = path.resolve(inputPath);

    let matchedPrefix = '';
    let relativePath = '';
    let prefixMatched = false;

    for (const prefix of this.resolvedPrefixes) {
      if (resolvedPath === prefix || resolvedPath.startsWith(prefix + path.sep)) {
        prefixMatched = true;
        matchedPrefix = prefix;
        relativePath = resolvedPath.slice(prefix.length);
        if (relativePath.startsWith(path.sep)) {
          relativePath = relativePath.slice(1);
        }
        break;
      }
    }

    if (!prefixMatched) {
      return {
        isValid: false,
        resolvedPath,
        relativePath: '',
        matchedPrefix: '',
        errors: ['Path is outside allowed directories'],
      };
    }

    const pathParts = resolvedPath.split(path.sep);
    if (!this.config.allowHidden) {
      for (const part of pathParts) {
        if (part.startsWith('.') && part !== '.' && part !== '..') {
          errors.push('Hidden files/directories are not allowed');
          break;
        }
      }
    }

    const basename = path.basename(resolvedPath);
    if (this.config.blockedNames.includes(basename)) {
      errors.push(`File name "${basename}" is blocked`);
    }

    const ext = path.extname(resolvedPath).toLowerCase();
    if (this.config.blockedExtensions.includes(ext)) {
      errors.push(`File extension "${ext}" is blocked`);
    }

    return {
      isValid: errors.length === 0,
      resolvedPath,
      relativePath,
      matchedPrefix,
      errors,
    };
  }

  /**
   * Securely joins path segments within allowed directories.
   *
   * @param prefix - Base directory (must be in allowedPrefixes)
   * @param segments - Path segments to join
   * @returns Validated resolved path
   */
  async securePath(prefix: string, ...segments: string[]): Promise<string> {
    // Join the segments
    const joined = path.join(prefix, ...segments);

    // Validate the result
    return this.validateOrThrow(joined);
  }

  /**
   * Adds a prefix to the allowed list at runtime.
   *
   * @param prefix - Prefix to add
   */
  addPrefix(prefix: string): void {
    const resolved = path.resolve(prefix);
    if (!this.resolvedPrefixes.includes(resolved)) {
      this.config.allowedPrefixes.push(prefix);
      this.resolvedPrefixes.push(resolved);
    }
  }

  /**
   * Returns the current allowed prefixes.
   */
  getAllowedPrefixes(): readonly string[] {
    return [...this.resolvedPrefixes];
  }

  /**
   * Checks if a path is within allowed prefixes (quick check).
   */
  isWithinAllowed(inputPath: string): boolean {
    try {
      const resolved = path.resolve(inputPath);
      return this.resolvedPrefixes.some(
        prefix => resolved === prefix || resolved.startsWith(prefix + path.sep)
      );
    } catch {
      return false;
    }
  }
}

/**
 * Factory function to create a path validator for a project directory.
 *
 * @param projectRoot - Root directory of the project
 * @returns Configured PathValidator
 */
export function createProjectPathValidator(projectRoot: string): PathValidator {
  const srcDir = path.join(projectRoot, 'src');
  const testDir = path.join(projectRoot, 'tests');
  const docsDir = path.join(projectRoot, 'docs');

  return new PathValidator({
    allowedPrefixes: [srcDir, testDir, docsDir],
    allowHidden: false,
  });
}

/**
 * Factory function to create a path validator for the entire project.
 *
 * @param projectRoot - Root directory of the project
 * @returns Configured PathValidator
 */
export function createFullProjectPathValidator(projectRoot: string): PathValidator {
  return new PathValidator({
    allowedPrefixes: [projectRoot],
    allowHidden: true, // Allow .gitignore, etc.
    blockedNames: [
      ...DEFAULT_BLOCKED_NAMES,
      'node_modules', // Block access to node_modules
    ],
  });
}

/**
 * PluginIntegrityVerifier — install-layer security for plugin supply chain.
 *
 * Implements P1 of ADR-145 (ruvnet/ruflo#2254): Stage-1 Ed25519 signature
 * verification at `plugins install`. Stage-2 (semantic-intent scan against
 * SCH attacks) lands in P2; per-namespace write ACLs land in P3-P4.
 *
 * Threat model
 * ------------
 * Ruflo's plugin install path fetches manifests from IPFS via Pinata with
 * NO signature verification and NO intent analysis. Two attacks land today:
 *
 *   - DDIPE (arXiv:2604.03081): malicious logic embedded in plugin docs and
 *     config templates. 11.6-33.5% bypass rate across 4 frameworks/5 models;
 *     2.5% evade both detection and alignment. Stage-1 signing blocks the
 *     static-payload variants.
 *
 *   - SCH (arXiv:2605.14460): malicious intent wrapped as natural-language
 *     "compliance rules" in plugin descriptions. The agent generates the
 *     harmful code at runtime — no static payload exists. 77.67% breach
 *     success, 0.00% scanner detection. Stage-2 (P2) catches this; Stage-1
 *     does not.
 *
 * Scope (P1)
 * ----------
 * - Ed25519 signature verification of a detached signature over the manifest.
 * - Trust-anchor allowlist: the publisher's signing key fingerprint must be
 *   in `trust-anchors.json`, gated on CODEOWNERS review.
 * - Backwards compatible: default mode is warn-only. `CLAUDE_FLOW_STRICT_PLUGINS=true`
 *   makes verification a hard gate.
 *
 * Non-goals (P1)
 * --------------
 * - Semantic intent scan (SCH defence). Lands in P2 with a pattern-rule
 *   fallback for environments without LLM credentials.
 * - Sandboxing the plugin runtime. Orthogonal blast-radius concern.
 *
 * Reference: ADR-145, arXiv:2605.14460 (SCH), arXiv:2604.03081 (DDIPE),
 * arXiv:2604.16548 (Mnemonic Sovereignty survey).
 */

import { createHash } from 'node:crypto';
import * as nodeCrypto from 'node:crypto';

export interface PluginManifest {
  readonly id: string;
  readonly version: string;
  /** Anything else; only `id` + `version` matter for the integrity hash. */
  readonly [extra: string]: unknown;
}

export interface SignedPluginManifest {
  readonly manifest: PluginManifest;
  /** Hex-encoded SHA-256 of the canonical JSON serialisation of manifest. */
  readonly manifestHash: string;
  /** Hex-encoded detached Ed25519 signature over `manifestHash` bytes. */
  readonly signature: string;
  /** Hex-encoded Ed25519 public key of the signer. */
  readonly publicKey: string;
}

export interface TrustAnchor {
  /** Hex-encoded Ed25519 public key the publisher signs with. */
  readonly publicKey: string;
  /** Human-readable owner — for audit, not for trust decisions. */
  readonly owner: string;
  /** Optional ISO 8601 date after which this anchor is no longer trusted. */
  readonly expiresAt?: string;
  /** Optional plugin id glob this anchor is authoritative for (e.g. `@claude-flow/*`). */
  readonly scope?: string;
}

export interface TrustAnchors {
  readonly version: 1;
  readonly anchors: ReadonlyArray<TrustAnchor>;
}

export type VerificationStatus =
  | 'pass'
  | 'signature-missing'
  | 'signature-invalid'
  | 'manifest-hash-mismatch'
  | 'unknown-signer'
  | 'signer-expired'
  | 'signer-out-of-scope';

export interface VerificationResult {
  readonly status: VerificationStatus;
  readonly pluginId: string;
  readonly signerFingerprint?: string;
  /** Verification timestamp — useful for telemetry correlation. */
  readonly ts: number;
  /** Operator-facing detail; do not parse — log only. */
  readonly detail?: string;
}

export interface VerifierConfig {
  readonly trustAnchors: TrustAnchors;
  /**
   * When true, `verify` returns the actual failure status. When false (legacy
   * mode), `verify` returns the failure status BUT callers may choose to
   * proceed with a warning — the strictness gate lives at the caller, not
   * here, so the verifier itself is always pure.
   */
  readonly strict?: boolean;
  /** Optional now-provider for tests. */
  readonly now?: () => number;
}

/**
 * Canonical JSON serialisation for hashing. Deterministic key ordering at
 * every nesting level. Pure; identical input → identical output bytes.
 */
export function canonicalize(value: unknown): string {
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return '[' + value.map(canonicalize).join(',') + ']';
  const obj = value as Record<string, unknown>;
  const keys = Object.keys(obj).sort();
  return '{' + keys.map(k => JSON.stringify(k) + ':' + canonicalize(obj[k])).join(',') + '}';
}

/** Hex-encoded SHA-256 of the canonical-JSON manifest. */
export function hashManifest(manifest: PluginManifest): string {
  return createHash('sha256').update(canonicalize(manifest)).digest('hex');
}

/** Short fingerprint for telemetry — first 16 hex chars of the key. */
export function fingerprint(publicKey: string): string {
  return publicKey.slice(0, 16);
}

/**
 * Find the trust anchor that vouches for a manifest. Returns the matched
 * anchor (with anchor.publicKey === signer.publicKey) or null.
 *
 * Scope-matching uses a minimal glob: `*` at the end of the scope string
 * matches any suffix. Empty/missing scope matches every plugin id.
 */
export function findAnchor(
  anchors: ReadonlyArray<TrustAnchor>,
  pluginId: string,
  signerPublicKey: string,
  now: number,
): TrustAnchor | null {
  for (const a of anchors) {
    if (a.publicKey !== signerPublicKey) continue;
    if (a.expiresAt && new Date(a.expiresAt).getTime() <= now) continue;
    if (!a.scope || a.scope === '*' || a.scope === pluginId) return a;
    if (a.scope.endsWith('*') && pluginId.startsWith(a.scope.slice(0, -1))) return a;
  }
  return null;
}

/**
 * `PluginIntegrityVerifier` — Stage-1 verifier (signature + trust anchor).
 *
 * Pure-ish: holds the trust-anchor list and clock, no other state. Safe to
 * construct per-invocation or share.
 */
export class PluginIntegrityVerifier {
  constructor(private readonly config: VerifierConfig) {}

  /**
   * Verify a signed manifest. Returns the verification status; the caller
   * decides what to do with `signature-missing` / `manifest-hash-mismatch`
   * etc. based on its strict-mode policy.
   */
  async verify(signed: SignedPluginManifest): Promise<VerificationResult> {
    const now = (this.config.now ?? Date.now)();
    const pluginId = signed.manifest?.id ?? '<unknown>';

    if (!signed.signature || !signed.publicKey) {
      return { status: 'signature-missing', pluginId, ts: now };
    }

    // Re-hash the manifest and compare to the signed hash.
    const recomputed = hashManifest(signed.manifest);
    if (recomputed !== signed.manifestHash) {
      return {
        status: 'manifest-hash-mismatch',
        pluginId,
        signerFingerprint: fingerprint(signed.publicKey),
        ts: now,
        detail: `expected ${signed.manifestHash}, got ${recomputed}`,
      };
    }

    // Find a trust anchor that vouches for this signer + plugin.
    const anchor = findAnchor(this.config.trustAnchors.anchors, pluginId, signed.publicKey, now);
    if (!anchor) {
      return {
        status: 'unknown-signer',
        pluginId,
        signerFingerprint: fingerprint(signed.publicKey),
        ts: now,
      };
    }

    // Ed25519 verify. Probe @noble/ed25519 (already a workspace dep); fall
    // back to the failure status if it isn't resolvable in this environment
    // (mirrors verify.mjs's #1880 precondition pattern).
    const ed = await loadEd25519();
    if (!ed) {
      return {
        status: 'signature-invalid',
        pluginId,
        signerFingerprint: fingerprint(signed.publicKey),
        ts: now,
        detail: '@noble/ed25519 not available — cannot verify',
      };
    }

    // Required by @noble/ed25519 v2 for sync sha512.
    if (!ed.etc.sha512Sync) {
      ed.etc.sha512Sync = (...m: Uint8Array[]): Uint8Array => {
        const h = nodeCrypto.createHash('sha512');
        for (const x of m) h.update(x);
        return h.digest();
      };
    }

    let ok = false;
    try {
      const sigBytes = hexToBytes(signed.signature);
      const msgBytes = hexToBytes(signed.manifestHash);
      const pubBytes = hexToBytes(signed.publicKey);
      ok = await ed.verify(sigBytes, msgBytes, pubBytes);
    } catch {
      ok = false;
    }

    if (!ok) {
      return {
        status: 'signature-invalid',
        pluginId,
        signerFingerprint: fingerprint(signed.publicKey),
        ts: now,
      };
    }

    return { status: 'pass', pluginId, signerFingerprint: fingerprint(signed.publicKey), ts: now };
  }
}

// ─── helpers ────────────────────────────────────────────────────────────

function hexToBytes(hex: string): Uint8Array {
  const out = new Uint8Array(hex.length >>> 1);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(hex.substr(i * 2, 2), 16);
  return out;
}

interface NobleEd25519 {
  verify(sig: Uint8Array, msg: Uint8Array, pub: Uint8Array): Promise<boolean>;
  etc: { sha512Sync?: (...m: Uint8Array[]) => Uint8Array };
}

async function loadEd25519(): Promise<NobleEd25519 | null> {
  try {
    const mod = await import('@noble/ed25519');
    return mod as unknown as NobleEd25519;
  } catch {
    return null;
  }
}

/**
 * Safe Executor - HIGH-1 Remediation
 *
 * Fixes command injection vulnerabilities by:
 * - Using execFile instead of exec with shell
 * - Validating all command arguments
 * - Implementing command allowlist
 * - Sanitizing command inputs
 *
 * Security Properties:
 * - No shell interpretation
 * - Argument validation
 * - Command allowlist enforcement
 * - Timeout controls
 * - Resource limits
 *
 * @module v3/security/safe-executor
 */

import { execFile, spawn, ChildProcess } from 'child_process';
import { promisify } from 'util';
import * as path from 'path';

const execFileAsync = promisify(execFile);

export interface ExecutorConfig {
  /**
   * Allowed commands (allowlist).
   * Only commands in this list can be executed.
   */
  allowedCommands: string[];

  /**
   * Blocked argument patterns (regex strings).
   * Arguments matching these patterns are rejected.
   */
  blockedPatterns?: string[];

  /**
   * Maximum execution timeout in milliseconds.
   * Default: 30000 (30 seconds)
   */
  timeout?: number;

  /**
   * Maximum buffer size for stdout/stderr.
   * Default: 10MB
   */
  maxBuffer?: number;

  /**
   * Working directory for command execution.
   * Default: process.cwd()
   */
  cwd?: string;

  /**
   * Environment variables to include.
   * Default: process.env
   */
  env?: NodeJS.ProcessEnv;

  /**
   * Whether to allow sudo commands.
   * Default: false
   */
  allowSudo?: boolean;
}

export interface ExecutionResult {
  stdout: string;
  stderr: string;
  exitCode: number;
  command: string;
  args: string[];
  duration: number;
}

export interface StreamingExecutor {
  process: ChildProcess;
  stdout: NodeJS.ReadableStream | null;
  stderr: NodeJS.ReadableStream | null;
  promise: Promise<ExecutionResult>;
}

export class SafeExecutorError extends Error {
  constructor(
    message: string,
    public readonly code: string,
    public readonly command?: string,
    public readonly args?: string[],
  ) {
    super(message);
    this.name = 'SafeExecutorError';
  }
}

/**
 * Default blocked argument patterns.
 * These patterns indicate potential command injection attempts.
 */
const DEFAULT_BLOCKED_PATTERNS = [
  // Shell metacharacters
  ';',
  '&&',
  '||',
  '|',
  '`',
  '$(',
  '${',
  // Redirection
  '>',
  '<',
  '>>',
  // Background execution
  '&',
  // Newlines (command chaining)
  '\n',
  '\r',
  // Null byte injection
  '\0',
  // Command substitution
  '$()',
];

/**
 * Commands that are inherently dangerous and should never be allowed.
 */
const DANGEROUS_COMMANDS = [
  'rm',
  'rmdir',
  'del',
  'format',
  'mkfs',
  'dd',
  'chmod',
  'chown',
  'kill',
  'killall',
  'pkill',
  'reboot',
  'shutdown',
  'init',
  'poweroff',
  'halt',
];

/**
 * Safe command executor that prevents command injection.
 *
 * This class replaces unsafe exec() and spawn({shell: true}) calls
 * with validated execFile() calls.
 *
 * @example
 * ```typescript
 * const executor = new SafeExecutor({
 *   allowedCommands: ['git', 'npm', 'node']
 * });
 *
 * const result = await executor.execute('git', ['status']);
 * ```
 */
export class SafeExecutor {
  private readonly config: Required<ExecutorConfig>;
  private readonly blockedPatterns: RegExp[];

  constructor(config: ExecutorConfig) {
    this.config = {
      allowedCommands: config.allowedCommands,
      blockedPatterns: config.blockedPatterns ?? DEFAULT_BLOCKED_PATTERNS,
      timeout: config.timeout ?? 30000,
      maxBuffer: config.maxBuffer ?? 10 * 1024 * 1024, // 10MB
      cwd: config.cwd ?? process.cwd(),
      env: config.env ?? process.env,
      allowSudo: config.allowSudo ?? false,
    };

    // Compile blocked patterns for performance
    this.blockedPatterns = this.config.blockedPatterns.map(
      pattern => new RegExp(this.escapeRegExp(pattern), 'i')
    );

    this.validateConfig();
  }

  /**
   * Escapes special regex characters.
   */
  private escapeRegExp(str: string): string {
    return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }

  /**
   * Validates executor configuration.
   */
  private validateConfig(): void {
    if (this.config.allowedCommands.length === 0) {
      throw new SafeExecutorError(
        'At least one allowed command must be specified',
        'EMPTY_ALLOWLIST'
      );
    }

    // Check for dangerous commands in allowlist
    const dangerousAllowed = this.config.allowedCommands.filter(
      cmd => DANGEROUS_COMMANDS.includes(path.basename(cmd))
    );

    if (dangerousAllowed.length > 0) {
      throw new SafeExecutorError(
        `Dangerous commands cannot be allowed: ${dangerousAllowed.join(', ')}`,
        'DANGEROUS_COMMAND_ALLOWED'
      );
    }
  }

  /**
   * Validates a command against the allowlist.
   *
   * @param command - Command to validate
   * @throws SafeExecutorError if command is not allowed
   */
  private validateCommand(command: string): void {
    const basename = path.basename(command);

    // Check if command is allowed
    const isAllowed = this.config.allowedCommands.some(allowed => {
      const allowedBasename = path.basename(allowed);
      return command === allowed || basename === allowedBasename;
    });

    if (!isAllowed) {
      throw new SafeExecutorError(
        `Command not in allowlist: ${command}`,
        'COMMAND_NOT_ALLOWED',
        command
      );
    }

    // Check for sudo
    if (!this.config.allowSudo && (command === 'sudo' || basename === 'sudo')) {
      throw new SafeExecutorError(
        'Sudo commands are not allowed',
        'SUDO_NOT_ALLOWED',
        command
      );
    }
  }

  /**
   * Validates command arguments for injection patterns.
   *
   * @param args - Arguments to validate
   * @throws SafeExecutorError if arguments contain dangerous patterns
   */
  private validateArguments(args: string[]): void {
    for (const arg of args) {
      // Check for null bytes
      if (arg.includes('\0')) {
        throw new SafeExecutorError(
          'Null byte detected in argument',
          'NULL_BYTE_INJECTION',
          undefined,
          args
        );
      }

      // Check against blocked patterns
      for (const pattern of this.blockedPatterns) {
        if (pattern.test(arg)) {
          throw new SafeExecutorError(
            `Dangerous pattern detected in argument: ${arg}`,
            'DANGEROUS_PATTERN',
            undefined,
            args
          );
        }
      }

      // Check for command chaining attempts
      if (/^-.*[;&|]/.test(arg)) {
        throw new SafeExecutorError(
          `Potential command chaining in argument: ${arg}`,
          'COMMAND_CHAINING',
          undefined,
          args
        );
      }
    }
  }

  /**
   * Sanitizes a single argument.
   *
   * @param arg - Argument to sanitize
   * @returns Sanitized argument
   */
  sanitizeArgument(arg: string): string {
    // Remove null bytes
    let sanitized = arg.replace(/\0/g, '');

    // Remove shell metacharacters
    sanitized = sanitized.replace(/[;&|`$(){}><\n\r]/g, '');

    return sanitized;
  }

  /**
   * Executes a command safely.
   *
   * @param command - Command to execute (must be in allowlist)
   * @param args - Command arguments
   * @returns Execution result
   * @throws SafeExecutorError on validation failure or execution error
   */
  async execute(command: string, args: string[] = []): Promise<ExecutionResult> {
    const startTime = Date.now();

    // Validate command
    this.validateCommand(command);

    // Validate arguments
    this.validateArguments(args);

    try {
      // Execute command WITHOUT shell
      const { stdout, stderr } = await execFileAsync(command, args, {
        cwd: this.config.cwd,
        env: this.config.env,
        timeout: this.config.timeout,
        maxBuffer: this.config.maxBuffer,
        shell: false, // CRITICAL: Never use shell
        windowsHide: true,
      });

      return {
        stdout: stdout.toString(),
        stderr: stderr.toString(),
        exitCode: 0,
        command,
        args,
        duration: Date.now() - startTime,
      };
    } catch (error: any) {
      // Handle execution errors
      if (error.killed) {
        throw new SafeExecutorError(
          'Command execution timed out',
          'TIMEOUT',
          command,
          args
        );
      }

      if (error.code === 'ENOENT') {
        throw new SafeExecutorError(
          `Command not found: ${command}`,
          'COMMAND_NOT_FOUND',
          command,
          args
        );
      }

      // Return result with non-zero exit code
      return {
        stdout: error.stdout?.toString() ?? '',
        stderr: error.stderr?.toString() ?? error.message,
        exitCode: error.code ?? 1,
        command,
        args,
        duration: Date.now() - startTime,
      };
    }
  }

  /**
   * Executes a command with streaming output.
   *
   * @param command - Command to execute
   * @param args - Command arguments
   * @returns Streaming executor with process handles
   */
  executeStreaming(command: string, args: string[] = []): StreamingExecutor {
    const startTime = Date.now();

    // Validate command
    this.validateCommand(command);

    // Validate arguments
    this.validateArguments(args);

    // Spawn process WITHOUT shell
    const childProcess = spawn(command, args, {
      cwd: this.config.cwd,
      env: this.config.env,
      timeout: this.config.timeout,
      shell: false, // CRITICAL: Never use shell
      windowsHide: true,
    });

    const promise = new Promise<ExecutionResult>((resolve, reject) => {
      let stdout = '';
      let stderr = '';

      childProcess.stdout?.on('data', (data: Buffer) => {
        stdout += data.toString();
      });

      childProcess.stderr?.on('data', (data: Buffer) => {
        stderr += data.toString();
      });

      childProcess.on('close', (code) => {
        resolve({
          stdout,
          stderr,
          exitCode: code ?? 0,
          command,
          args,
          duration: Date.now() - startTime,
        });
      });

      childProcess.on('error', (error) => {
        reject(new SafeExecutorError(
          error.message,
          'EXECUTION_ERROR',
          command,
          args
        ));
      });
    });

    return {
      process: childProcess,
      stdout: childProcess.stdout,
      stderr: childProcess.stderr,
      promise,
    };
  }

  /**
   * Adds a command to the allowlist at runtime.
   *
   * @param command - Command to add
   */
  allowCommand(command: string): void {
    const basename = path.basename(command);

    if (DANGEROUS_COMMANDS.includes(basename)) {
      throw new SafeExecutorError(
        `Cannot allow dangerous command: ${command}`,
        'DANGEROUS_COMMAND'
      );
    }

    if (!this.config.allowedCommands.includes(command)) {
      this.config.allowedCommands.push(command);
    }
  }

  /**
   * Checks if a command is allowed.
   *
   * @param command - Command to check
   * @returns True if command is allowed
   */
  isCommandAllowed(command: string): boolean {
    const basename = path.basename(command);
    return this.config.allowedCommands.some(allowed => {
      const allowedBasename = path.basename(allowed);
      return command === allowed || basename === allowedBasename;
    });
  }

  /**
   * Returns the current allowlist.
   */
  getAllowedCommands(): readonly string[] {
    return [...this.config.allowedCommands];
  }
}

/**
 * Factory function to create a safe executor for common development tasks.
 *
 * @returns Configured SafeExecutor for git, npm, and node
 */
export function createDevelopmentExecutor(): SafeExecutor {
  return new SafeExecutor({
    allowedCommands: [
      'git',
      'npm',
      'node',
      'tsc',
      'vitest',
      'eslint',
      'prettier',
    ],
  });
}

/**
 * Factory function to create a CLI executor.
 * Allows commands commonly needed by CLI command handlers.
 *
 * @returns Configured SafeExecutor for CLI operations
 */
export function createCliExecutor(): SafeExecutor {
  return new SafeExecutor({
    allowedCommands: [
      'git',
      'npm',
      'npx',
      'node',
      'docker',
      'which',
      'tsc',
      'vitest',
    ],
    timeout: 60000,
  });
}

/**
 * Factory function to create a read-only executor.
 * Only allows commands that read without modifying.
 *
 * @returns Configured SafeExecutor for read operations
 */
export function createReadOnlyExecutor(): SafeExecutor {
  return new SafeExecutor({
    allowedCommands: [
      'git',
      'cat',
      'head',
      'tail',
      'ls',
      'find',
      'grep',
      'which',
      'echo',
    ],
    timeout: 10000,
  });
}

/**
 * Token Generator - Secure Token Generation
 *
 * Provides cryptographically secure token generation for:
 * - JWT tokens
 * - Session tokens
 * - CSRF tokens
 * - API tokens
 * - Verification codes
 *
 * Security Properties:
 * - Uses crypto.randomBytes for all randomness
 * - Configurable entropy levels
 * - Timing-safe comparison
 * - Token expiration handling
 *
 * @module v3/security/token-generator
 */

import { randomBytes, createHmac, timingSafeEqual } from 'crypto';

export interface TokenConfig {
  /**
   * Default token length in bytes.
   * Default: 32 (256 bits)
   */
  defaultLength?: number;

  /**
   * Token encoding format.
   * Default: 'base64url'
   */
  encoding?: 'hex' | 'base64' | 'base64url';

  /**
   * HMAC secret for signed tokens.
   */
  hmacSecret?: string;

  /**
   * Default expiration time in seconds.
   * Default: 3600 (1 hour)
   */
  defaultExpiration?: number;
}

export interface Token {
  value: string;
  createdAt: Date;
  expiresAt: Date;
  metadata?: Record<string, unknown>;
}

export interface SignedToken {
  token: string;
  signature: string;
  combined: string;
  createdAt: Date;
  expiresAt: Date;
}

export interface VerificationCode {
  code: string;
  createdAt: Date;
  expiresAt: Date;
  attempts: number;
  maxAttempts: number;
}

export class TokenGeneratorError extends Error {
  constructor(
    message: string,
    public readonly code: string,
  ) {
    super(message);
    this.name = 'TokenGeneratorError';
  }
}

/**
 * Secure token generator.
 *
 * @example
 * ```typescript
 * const generator = new TokenGenerator({ hmacSecret: 'secret' });
 *
 * // Generate session token
 * const session = generator.generateSessionToken();
 *
 * // Generate signed token
 * const signed = generator.generateSignedToken({ userId: '123' });
 *
 * // Verify signed token
 * const isValid = generator.verifySignedToken(signed.combined);
 * ```
 */
export class TokenGenerator {
  private readonly config: Required<TokenConfig>;

  constructor(config: TokenConfig = {}) {
    this.config = {
      defaultLength: config.defaultLength ?? 32,
      encoding: config.encoding ?? 'base64url',
      hmacSecret: config.hmacSecret ?? '',
      defaultExpiration: config.defaultExpiration ?? 3600,
    };

    if (this.config.defaultLength < 16) {
      throw new TokenGeneratorError(
        'Token length must be at least 16 bytes',
        'INVALID_LENGTH'
      );
    }
  }

  /**
   * Generates a random token.
   *
   * @param length - Token length in bytes
   * @returns Random token string
   */
  generate(length?: number): string {
    const len = length ?? this.config.defaultLength;
    const buffer = randomBytes(len);
    return this.encode(buffer);
  }

  /**
   * Generates a token with expiration.
   *
   * @param expirationSeconds - Expiration time in seconds
   * @param metadata - Optional metadata to attach
   * @returns Token with expiration
   */
  generateWithExpiration(
    expirationSeconds?: number,
    metadata?: Record<string, unknown>
  ): Token {
    const expiration = expirationSeconds ?? this.config.defaultExpiration;
    const now = new Date();
    const expiresAt = new Date(now.getTime() + expiration * 1000);

    return {
      value: this.generate(),
      createdAt: now,
      expiresAt,
      metadata,
    };
  }

  /**
   * Generates a session token (URL-safe).
   *
   * @param length - Token length in bytes (default: 32)
   * @returns Session token
   */
  generateSessionToken(length = 32): Token {
    return this.generateWithExpiration(this.config.defaultExpiration);
  }

  /**
   * Generates a CSRF token.
   *
   * @returns CSRF token (shorter expiration)
   */
  generateCsrfToken(): Token {
    return this.generateWithExpiration(1800); // 30 minutes
  }

  /**
   * Generates an API token with prefix.
   *
   * @param prefix - Token prefix (e.g., 'cf_')
   * @returns Prefixed API token
   */
  generateApiToken(prefix = 'cf_'): Token {
    const tokenBody = this.generate(32);
    const now = new Date();

    return {
      value: `${prefix}${tokenBody}`,
      createdAt: now,
      expiresAt: new Date(now.getTime() + 365 * 24 * 60 * 60 * 1000), // 1 year
    };
  }

  /**
   * Generates a numeric verification code.
   *
   * @param length - Number of digits (default: 6)
   * @param expirationMinutes - Expiration in minutes (default: 10)
   * @param maxAttempts - Maximum verification attempts (default: 3)
   * @returns Verification code
   */
  generateVerificationCode(
    length = 6,
    expirationMinutes = 10,
    maxAttempts = 3
  ): VerificationCode {
    const buffer = randomBytes(length);
    let code = '';

    for (let i = 0; i < length; i++) {
      code += (buffer[i] % 10).toString();
    }

    const now = new Date();

    return {
      code,
      createdAt: now,
      expiresAt: new Date(now.getTime() + expirationMinutes * 60 * 1000),
      attempts: 0,
      maxAttempts,
    };
  }

  /**
   * Generates a signed token using HMAC.
   *
   * @param payload - Data to include in token
   * @param expirationSeconds - Token expiration
   * @returns Signed token
   */
  generateSignedToken(
    payload: Record<string, unknown>,
    expirationSeconds?: number
  ): SignedToken {
    if (!this.config.hmacSecret) {
      throw new TokenGeneratorError(
        'HMAC secret required for signed tokens',
        'NO_SECRET'
      );
    }

    const expiration = expirationSeconds ?? this.config.defaultExpiration;
    const now = new Date();
    const expiresAt = new Date(now.getTime() + expiration * 1000);

    const tokenData = {
      ...payload,
      iat: now.getTime(),
      exp: expiresAt.getTime(),
      nonce: this.generate(8),
    };

    const token = Buffer.from(JSON.stringify(tokenData)).toString('base64url');
    const signature = this.sign(token);

    return {
      token,
      signature,
      combined: `${token}.${signature}`,
      createdAt: now,
      expiresAt,
    };
  }

  /**
   * Verifies a signed token.
   *
   * @param combined - Combined token string (token.signature)
   * @returns Decoded payload if valid, null otherwise
   */
  verifySignedToken(combined: string): Record<string, unknown> | null {
    if (!this.config.hmacSecret) {
      throw new TokenGeneratorError(
        'HMAC secret required for signed tokens',
        'NO_SECRET'
      );
    }

    const parts = combined.split('.');
    if (parts.length !== 2) {
      return null;
    }

    const [token, signature] = parts;

    // Verify signature
    const expectedSignature = this.sign(token);

    try {
      const sigBuffer = Buffer.from(signature, 'base64url');
      const expectedBuffer = Buffer.from(expectedSignature, 'base64url');

      if (sigBuffer.length !== expectedBuffer.length) {
        return null;
      }

      if (!timingSafeEqual(sigBuffer, expectedBuffer)) {
        return null;
      }
    } catch {
      return null;
    }

    // Decode and validate payload
    try {
      const payload = JSON.parse(Buffer.from(token, 'base64url').toString());

      // Check expiration
      if (payload.exp && payload.exp < Date.now()) {
        return null;
      }

      return payload;
    } catch {
      return null;
    }
  }

  /**
   * Generates a refresh token pair.
   *
   * @returns Access and refresh tokens
   */
  generateTokenPair(): {
    accessToken: Token;
    refreshToken: Token;
  } {
    return {
      accessToken: this.generateWithExpiration(900), // 15 minutes
      refreshToken: this.generateWithExpiration(604800), // 7 days
    };
  }

  /**
   * Generates a password reset token.
   *
   * @returns Password reset token (short expiration)
   */
  generatePasswordResetToken(): Token {
    return this.generateWithExpiration(1800); // 30 minutes
  }

  /**
   * Generates an email verification token.
   *
   * @returns Email verification token
   */
  generateEmailVerificationToken(): Token {
    return this.generateWithExpiration(86400); // 24 hours
  }

  /**
   * Generates a unique request ID.
   *
   * @returns Request ID (shorter, for logging)
   */
  generateRequestId(): string {
    return this.generate(8);
  }

  /**
   * Generates a correlation ID for distributed tracing.
   *
   * @returns Correlation ID
   */
  generateCorrelationId(): string {
    const timestamp = Date.now().toString(36);
    const random = this.generate(8);
    return `${timestamp}-${random}`;
  }

  /**
   * Checks if a token has expired.
   *
   * @param token - Token to check
   * @returns True if expired
   */
  isExpired(token: Token | VerificationCode): boolean {
    return token.expiresAt < new Date();
  }

  /**
   * Compares two tokens in constant time.
   *
   * @param a - First token
   * @param b - Second token
   * @returns True if equal
   */
  compare(a: string, b: string): boolean {
    if (a.length !== b.length) {
      return false;
    }

    try {
      const bufferA = Buffer.from(a);
      const bufferB = Buffer.from(b);
      return timingSafeEqual(bufferA, bufferB);
    } catch {
      return false;
    }
  }

  /**
   * Signs data using HMAC-SHA256.
   */
  private sign(data: string): string {
    return createHmac('sha256', this.config.hmacSecret)
      .update(data)
      .digest('base64url');
  }

  /**
   * Encodes bytes according to configuration.
   */
  private encode(buffer: Buffer): string {
    switch (this.config.encoding) {
      case 'hex':
        return buffer.toString('hex');
      case 'base64':
        return buffer.toString('base64');
      case 'base64url':
      default:
        return buffer.toString('base64url');
    }
  }
}

/**
 * Factory function to create a production token generator.
 *
 * @param hmacSecret - HMAC secret for signed tokens
 * @returns Configured TokenGenerator
 */
export function createTokenGenerator(hmacSecret: string): TokenGenerator {
  return new TokenGenerator({
    hmacSecret,
    defaultLength: 32,
    encoding: 'base64url',
  });
}

/**
 * Singleton instance for quick token generation without configuration.
 */
let defaultGenerator: TokenGenerator | null = null;

/**
 * Gets or creates the default token generator.
 * Note: Does not support signed tokens without configuration.
 */
export function getDefaultGenerator(): TokenGenerator {
  if (!defaultGenerator) {
    defaultGenerator = new TokenGenerator();
  }
  return defaultGenerator;
}

/**
 * Quick token generation functions.
 */
export const quickGenerate = {
  token: (length = 32) => getDefaultGenerator().generate(length),
  sessionToken: () => getDefaultGenerator().generateSessionToken(),
  csrfToken: () => getDefaultGenerator().generateCsrfToken(),
  apiToken: (prefix = 'cf_') => getDefaultGenerator().generateApiToken(prefix),
  verificationCode: (length = 6) => getDefaultGenerator().generateVerificationCode(length),
  requestId: () => getDefaultGenerator().generateRequestId(),
  correlationId: () => getDefaultGenerator().generateCorrelationId(),
};

/**
 * ToolOutputGuardrail — semantic screening of content returned by MCP tool
 * calls, memory reads, and external API responses before that content enters
 * agent reasoning. Closes the OWASP ASI01 (Agent Goal Hijacking) gap
 * identified in ruvnet/ruflo#2149 / ADR-131.
 *
 * Threat model
 * ------------
 * Attackers embed malicious instructions in content the agent retrieves
 * autonomously (web page, MCP tool response, memory entry). An LLM cannot
 * reliably distinguish instructions from data once both are in the prompt.
 * System-level per-boundary guardrails are the only category with
 * sub-millisecond latency and no model dependency (arXiv:2601.17548,
 * Jan 2026 systematic review).
 *
 * Scope
 * -----
 * - Detection only — does NOT modify the running prompt; callers decide
 *   what action to take (allow, flag, redact, reject) via `scanAndEnforce`.
 * - Synchronous pattern match — designed for <1ms p99 on typical tool
 *   responses (≤32KB). Large content is capped at `maxScanBytes` and the
 *   truncation itself is reported as a low-severity finding.
 * - Pure-function shape — no I/O, no async, no model calls. Safe to invoke
 *   in hot paths (every MCP tool result, every memory read).
 *
 * Non-goals
 * ---------
 * - Not a replacement for input validation at HTTP/CLI boundaries
 *   (InputValidator handles that). This is the *content* boundary.
 * - Not a model-based classifier. False-positive rate is bounded by
 *   pattern specificity; tune via `customPatterns` and `policy`.
 *
 * Reference: ADR-131, OpenAI Agents SDK ToolGuardrail API (March 2025).
 */

export type InjectionSeverity = 'low' | 'medium' | 'high' | 'critical';

export type InjectionCategory =
  | 'instruction-override'
  | 'role-hijack'
  | 'exfiltration'
  | 'jailbreak'
  | 'hidden-unicode'
  | 'embedded-system'
  | 'tool-spoofing'
  | 'truncation';

export interface InjectionFinding {
  /** Short label for the matched pattern (stable identifier for telemetry). */
  pattern: string;
  /** Risk weight assigned to this pattern. */
  severity: InjectionSeverity;
  /** Category for downstream classification + OWASP mapping. */
  category: InjectionCategory;
  /** Char offset of the first match in the scanned content. */
  position: number;
  /** Up to 80 chars of surrounding context for human triage (redacted in `sanitized`). */
  context: string;
}

export interface GuardrailResult {
  /** True iff no findings, or all findings under the `flag` policy threshold. */
  safe: boolean;
  /** Findings in the order they were detected. */
  findings: InjectionFinding[];
  /** Highest severity observed; `none` if findings is empty. */
  highest: InjectionSeverity | 'none';
}

export type GuardrailAction = 'allow' | 'flag' | 'redact' | 'reject';

export interface GuardrailConfig {
  /**
   * Per-severity action.
   * Defaults:
   *   low      → allow
   *   medium   → flag
   *   high     → redact
   *   critical → reject
   *
   * `allow`  — content passes through unchanged, no logging required.
   * `flag`   — content passes through; caller SHOULD log + monitor.
   * `redact` — matched substrings replaced with `[REDACTED:<pattern>]`.
   * `reject` — caller MUST drop the content and treat the tool call
   *            as failed (signal the agent that the tool returned an
   *            unsafe payload rather than letting the payload through).
   */
  policy?: Partial<Record<InjectionSeverity, GuardrailAction>>;

  /** Add domain-specific patterns without subclassing. */
  customPatterns?: Array<{
    label: string;
    regex: RegExp;
    severity: InjectionSeverity;
    category: InjectionCategory;
  }>;

  /**
   * Maximum bytes of content to scan. Beyond this, the tail is ignored and
   * a `truncation` finding is added at `medium`. Default: 1 MiB.
   * Set to 0 to disable truncation (scan everything; slower on huge blobs).
   */
  maxScanBytes?: number;
}

const DEFAULT_POLICY: Required<NonNullable<GuardrailConfig['policy']>> = {
  low: 'allow',
  medium: 'flag',
  high: 'redact',
  critical: 'reject',
};

const DEFAULT_MAX_SCAN_BYTES = 1024 * 1024;

/**
 * Built-in pattern library. Ordered by severity (critical first) so the
 * `highest` field reflects the worst category. Patterns are intentionally
 * conservative — they target the explicit instruction-override / role-hijack
 * shapes that show up in published indirect-injection corpora rather than
 * general "suspicious looking" text.
 */
const BUILTIN_PATTERNS: ReadonlyArray<{
  label: string;
  regex: RegExp;
  severity: InjectionSeverity;
  category: InjectionCategory;
}> = [
  // ── critical: instruction override + embedded system frames ──
  {
    label: 'ignore-previous-instructions',
    // Allow optional filler words between the verb and the temporal keyword
    // ("ignore the above", "disregard your earlier", "forget all prior").
    regex: /\b(?:ignore|disregard|forget)\s+(?:all\s+|any\s+|the\s+|my\s+|your\s+|these\s+|those\s+)?(?:previous|prior|above|earlier|preceding|aforementioned)\s+(?:instructions?|prompts?|rules?|directives?)\b/gi,
    severity: 'critical',
    category: 'instruction-override',
  },
  {
    label: 'chatml-frame',
    regex: /<\|(?:im_start|im_end|system|assistant|user|endoftext)\|>/gi,
    severity: 'critical',
    category: 'embedded-system',
  },
  {
    label: 'llama-inst-frame',
    regex: /\[\/?INST\]/g,
    severity: 'critical',
    category: 'embedded-system',
  },
  {
    label: 'exfiltrate-secret',
    regex: /\b(?:exfiltrate|leak|send|post|upload|transmit)\b[^.\n]{0,80}\b(?:secret|token|api[-_\s]?keys?|password|credential|env\s+vars?)\b/gi,
    severity: 'critical',
    category: 'exfiltration',
  },

  // ── high: role hijack + jailbreak + system tags + bidi unicode ──
  {
    label: 'system-tag-injection',
    regex: /<\/?system>/gi,
    severity: 'high',
    category: 'embedded-system',
  },
  {
    label: 'role-hijack-you-are-now',
    regex: /\byou\s+are\s+(?:now|actually|secretly)\s+(?:a|an|the)\s+/gi,
    severity: 'high',
    category: 'role-hijack',
  },
  {
    label: 'jailbreak-dan',
    regex: /\b(?:DAN(?:\s+mode)?|developer\s+mode|jailbreak\s+mode|do\s+anything\s+now)\b/gi,
    severity: 'high',
    category: 'jailbreak',
  },
  {
    label: 'new-instructions-directive',
    regex: /\b(?:new|updated|revised|additional)\s+(?:instructions?|task|directives?|objectives?)\s*[:.]/gi,
    severity: 'high',
    category: 'instruction-override',
  },
  {
    label: 'bidi-override',
    regex: /[‪-‮⁦-⁩]/g,
    severity: 'high',
    category: 'hidden-unicode',
  },

  // ── medium: softer role manipulation + tool spoofing ──
  {
    label: 'role-hijack-act-as',
    regex: /\b(?:act|behave|pretend|role[-\s]?play)\s+as\s+(?:if\s+)?(?:a|an|the)\s+/gi,
    severity: 'medium',
    category: 'role-hijack',
  },
  {
    label: 'tool-call-spoof',
    regex: /\b(?:tool_call|function_call|mcp_tool)\s*[:=]\s*["'{]/gi,
    severity: 'medium',
    category: 'tool-spoofing',
  },

  // ── low: zero-width whitespace (common in copy-paste attacks) ──
  {
    label: 'zero-width-char',
    regex: /[​-‍﻿]/g,
    severity: 'low',
    category: 'hidden-unicode',
  },
];

const SEVERITY_ORDER: Record<InjectionSeverity | 'none', number> = {
  none: 0,
  low: 1,
  medium: 2,
  high: 3,
  critical: 4,
};

function snippet(text: string, idx: number, len: number): string {
  const start = Math.max(0, idx - 24);
  const end = Math.min(text.length, idx + len + 24);
  const head = start > 0 ? '…' : '';
  const tail = end < text.length ? '…' : '';
  return head + text.slice(start, end).replace(/\s+/g, ' ') + tail;
}

function maxSeverity(a: InjectionSeverity | 'none', b: InjectionSeverity): InjectionSeverity {
  return SEVERITY_ORDER[a] >= SEVERITY_ORDER[b]
    ? (a === 'none' ? b : a)
    : b;
}

export class ToolOutputGuardrail {
  private readonly patterns: ReadonlyArray<typeof BUILTIN_PATTERNS[number]>;
  private readonly policy: Required<NonNullable<GuardrailConfig['policy']>>;
  private readonly maxScanBytes: number;

  constructor(config: GuardrailConfig = {}) {
    this.patterns = [...BUILTIN_PATTERNS, ...(config.customPatterns ?? [])];
    this.policy = { ...DEFAULT_POLICY, ...(config.policy ?? {}) };
    this.maxScanBytes = config.maxScanBytes ?? DEFAULT_MAX_SCAN_BYTES;
  }

  /**
   * Pure scan — no side effects, no content modification. Useful when the
   * caller wants to log findings but cannot drop the content (e.g. read-only
   * audit mode).
   */
  scan(content: string): GuardrailResult {
    if (typeof content !== 'string') {
      return { safe: true, findings: [], highest: 'none' };
    }

    let scanned = content;
    const findings: InjectionFinding[] = [];

    if (this.maxScanBytes > 0 && content.length > this.maxScanBytes) {
      scanned = content.slice(0, this.maxScanBytes);
      findings.push({
        pattern: 'content-truncated',
        severity: 'medium',
        category: 'truncation',
        position: this.maxScanBytes,
        context: `(content truncated at ${this.maxScanBytes} bytes; ${content.length - this.maxScanBytes} bytes unscanned)`,
      });
    }

    for (const { label, regex, severity, category } of this.patterns) {
      // Clone the RegExp so that the global-flag lastIndex state doesn't
      // leak between calls. Built-in patterns are immutable; user-supplied
      // patterns are also defensively cloned.
      const re = new RegExp(regex.source, regex.flags.includes('g') ? regex.flags : regex.flags + 'g');
      let match: RegExpExecArray | null;
      while ((match = re.exec(scanned)) !== null) {
        findings.push({
          pattern: label,
          severity,
          category,
          position: match.index,
          context: snippet(scanned, match.index, match[0].length),
        });
        // Defensive: zero-length match would loop forever
        if (match[0].length === 0) re.lastIndex++;
      }
    }

    let highest: InjectionSeverity | 'none' = 'none';
    for (const f of findings) highest = maxSeverity(highest, f.severity);

    const action = highest === 'none' ? 'allow' : this.policy[highest];
    const safe = action === 'allow' || action === 'flag';

    return { safe, findings, highest };
  }

  /**
   * Scan + enforce policy. Returns the content to pass forward (possibly
   * redacted or empty) plus the scan result and the action that was taken.
   * Callers should treat `reject` as "drop the tool result and signal an
   * error" — do NOT silently substitute empty content.
   */
  scanAndEnforce(content: string): {
    content: string;
    result: GuardrailResult;
    action: GuardrailAction;
  } {
    const result = this.scan(content);

    const action: GuardrailAction =
      result.highest === 'none' ? 'allow' : this.policy[result.highest];

    let outgoing = content;
    if (action === 'redact') {
      outgoing = this.redact(content, result.findings);
    } else if (action === 'reject') {
      outgoing = '';
    }

    return { content: outgoing, result, action };
  }

  /**
   * Replace each non-truncation finding's matched substring with
   * `[REDACTED:<pattern>]`. Truncation findings have no substring to redact
   * (their `position` is a length, not an offset into the content) and are
   * skipped. Idempotent for already-redacted strings.
   */
  private redact(content: string, findings: InjectionFinding[]): string {
    if (findings.length === 0) return content;

    // Build a single combined regex per pattern label to avoid replacing
    // overlapping matches multiple times.
    const labels = new Set(
      findings
        .filter((f) => f.category !== 'truncation')
        .map((f) => f.pattern)
    );

    let out = content;
    for (const { label, regex } of this.patterns) {
      if (!labels.has(label)) continue;
      const re = new RegExp(regex.source, regex.flags.includes('g') ? regex.flags : regex.flags + 'g');
      out = out.replace(re, `[REDACTED:${label}]`);
    }
    return out;
  }
}

/** Convenience factory that returns a guardrail with the default policy. */
export function createToolOutputGuardrail(config?: GuardrailConfig): ToolOutputGuardrail {
  return new ToolOutputGuardrail(config);
}

/**
 * One-shot helper for callers that just want a yes/no answer without
 * constructing a guardrail. Uses the default policy.
 */
export function isToolOutputSafe(content: string): boolean {
  return createToolOutputGuardrail().scan(content).safe;
}

